package org.project.control;

import org.project.dao.professori.ProfessoreDAO;
import org.project.dao.studenti.StudenteDAO;
import org.project.dao.wallets.PortafoglioDAO;
import org.project.dao.classi.SchoolClassDAO;
import org.project.exceptions.ControllerException;
import org.project.exceptions.CredenzialNonValideException;
import org.project.exceptions.DAOException;
import org.project.ing.classifunzionali.Hasher;
import org.project.ing.persistenza.DAOFactory;
import org.project.model.*;
import org.project.view.bean.ProfessoreBean;
import org.project.view.bean.SessioneBean;
import org.project.view.bean.StudenteBean;
import org.project.view.bean.SchoolClassBean;

import java.util.ArrayList;
import java.util.List;


/**
 * Controller applicativo per il login (locale e OAuth).
 * Stateless: nessun campo di istanza.
 * Riceve sempre StudenteBean o ProfessoreBean dalla view:
 *   - login locale:  bean con email + password, authProvider null
 *   - login OAuth:   bean con email + authProvider, password ignorata
 */
public class LoginAppController {

    // ── Login studente ────────────────────────────────────────────────────────

    public SessioneBean loginStudente(StudenteBean bean)
            throws CredenzialNonValideException, ControllerException {

        DAOFactory factory = DAOFactory.getDAOFactory();
        StudenteDAO studenteDAO = factory.createStudenteDAO();

        try {
            Studente trovato = studenteDAO.getStudenteByEmail(bean.getEmail());

            if (trovato == null) {
                throw new CredenzialNonValideException("Credenziali non valide.");
            }

            if (bean.getAuthProvider() == null) {
                // Login locale: verifica password
                if (!(trovato instanceof AutenticazioneLocale locale)) {
                    throw new CredenzialNonValideException(
                            "Questo account usa OAuth. Accedi con Google o Microsoft.");
                }
                if (!locale.passwordHash().equals(Hasher.codifica(bean.getPassword()))) {
                    throw new CredenzialNonValideException("Password errata.");
                }
            } else {
                // Login OAuth: verifica provider
                if (!(trovato instanceof AutenticazioneOAuth oauth)) {
                    throw new CredenzialNonValideException(
                            "Questo account usa email e password. Accedi localmente.");
                }
                if (oauth.ottieniProvider() != bean.getAuthProvider()) {
                    throw new CredenzialNonValideException(
                            "Questo account è registrato con: " + oauth.ottieniProvider());
                }
            }

            return creaSessioneStudente(trovato, factory);

        } catch (DAOException e) {
            throw new ControllerException("Errore durante il login studente.", e);
        }
    }

    // ── Login professore ──────────────────────────────────────────────────────

    public SessioneBean loginProfessore(ProfessoreBean bean)
            throws CredenzialNonValideException, ControllerException {

        DAOFactory factory = DAOFactory.getDAOFactory();
        ProfessoreDAO professoreDAO = factory.createProfessoreDAO();

        try {
            Professore trovato = professoreDAO.getProfessoreByEmail(bean.getEmail());

            if (trovato == null) {
                throw new CredenzialNonValideException("Credenziali non valide.");
            }

            if (bean.getAuthProvider() == null) {
                // Login locale
                if (!(trovato instanceof AutenticazioneLocale locale)) {
                    throw new CredenzialNonValideException(
                            "Questo account usa OAuth. Accedi con Google o Microsoft.");
                }
                if (!locale.passwordHash().equals(Hasher.codifica(bean.getPassword()))) {
                    throw new CredenzialNonValideException("Password errata.");
                }
            } else {
                // Login OAuth
                if (!(trovato instanceof AutenticazioneOAuth oauth)) {
                    throw new CredenzialNonValideException(
                            "Questo account usa email e password. Accedi localmente.");
                }
                if (oauth.ottieniProvider() != bean.getAuthProvider()) {
                    throw new CredenzialNonValideException(
                            "Questo account è registrato con: " + oauth.ottieniProvider());
                }
            }

            return creaSessioneProfessore(trovato, factory);

        } catch (DAOException e) {
            throw new ControllerException("Errore durante il login professore.", e);
        }
    }

    // ── Logout ────────────────────────────────────────────────────────────────

    public void logout(SessioneBean sessione) {
        SessionManager.getInstance().cancellaSessione(sessione.getId());
    }

    // ── Metodi privati ────────────────────────────────────────────────────────

    private SessioneBean creaSessioneStudente(Studente studente, DAOFactory factory)
            throws DAOException, ControllerException {

        PortafoglioDAO walletDAO = factory.createPortafoglioDAO();
        VirtualWallet wallet = walletDAO.getPortafoglioByEmail(studente.presentaEmail());

        if (wallet == null) {
            throw new ControllerException("Wallet non trovato per lo studente: dato corrotto.");
        }

        studente.assegnaWallet(wallet);
        Sessione sessione = SessionManager.getInstance().creaSessione(studente);

        StudenteBean studenteBean = new StudenteBean(
                studente.presentaEmail(),
                studente.presentaNome(),
                studente.presentaCognome()
        );

        if (studente.classeFrequentata() != null) {
            studenteBean.setNomeClasse(studente.classeFrequentata().nome());
        }

        studenteBean.resetPassword();

        return new SessioneBean(sessione.getToken(), studenteBean);
    }
    private SessioneBean creaSessioneProfessore(Professore professore, DAOFactory factory) throws DAOException {

        Sessione sessione = SessionManager.getInstance().creaSessione(professore);

        ProfessoreBean professoreBean = new ProfessoreBean(
                professore.presentaEmail(),
                professore.presentaNome(),
                professore.presentaCognome()
        );

        // IMPORTANTE: Crea StudenteDAO PRIMA di SchoolClassDAO per garantire l'iniezione delle dipendenze
        factory.createStudenteDAO();

        SchoolClassDAO classDAO = factory.createSchoolClassDAO();
        SessioneBean sessioneBean = new SessioneBean(sessione.getToken(), professoreBean);

        // Converti SchoolClass in SchoolClassBean
        List<SchoolClass> classi = classDAO.getClassiByProfessore(professore);
        List<SchoolClassBean> classiBeans = new ArrayList<>();
        for (SchoolClass c : classi) {
            classiBeans.add(toBean(c));
        }
        sessioneBean.setListaClassi(classiBeans);

        return sessioneBean;
    }

    // ── Conversione model → bean ──────────────────────────────────────────────

    private SchoolClassBean toBean(SchoolClass c) {
        ProfessoreBean profBean = new ProfessoreBean(
                c.teacher().presentaEmail(),
                c.teacher().presentaNome(),
                c.teacher().presentaCognome());
        List<StudenteBean> studentiBeans = new ArrayList<>();
        if (c.studenti() != null) {
            for (Studente s : c.studenti()) {
                studentiBeans.add(new StudenteBean(
                        s.presentaEmail(), s.presentaNome(), s.presentaCognome()));
            }
        }
        return new SchoolClassBean(c.nome(), profBean, c.budgetIniziale(), studentiBeans);
    }
}

package org.project.control;

import org.project.dao.professori.ProfessoreDAO;
import org.project.dao.studenti.StudenteDAO;
import org.project.dao.wallets.PortafoglioDAO;
import org.project.dao.classi.SchoolClassDAO;
import org.project.exceptions.ControllerException;
import org.project.exceptions.CredenzialNonValideException;
import org.project.exceptions.DAOException;
import org.project.ing.classifunzionali.Hasher;
import org.project.ing.persistenza.DAOFactory;
import org.project.model.*;
import org.project.view.bean.ProfessoreBean;
import org.project.view.bean.SessioneBean;
import org.project.view.bean.StudenteBean;
import org.project.view.bean.SchoolClassBean;

import java.util.ArrayList;
import java.util.List;


/**
 * Controller applicativo per il login (locale e OAuth).
 * Stateless: nessun campo di istanza.
 * Riceve sempre StudenteBean o ProfessoreBean dalla view:
 *   - login locale:  bean con email + password, authProvider null
 *   - login OAuth:   bean con email + authProvider, password ignorata
 */
public class LoginAppController {

    // ── Login studente ────────────────────────────────────────────────────────

    public SessioneBean loginStudente(StudenteBean bean)
            throws CredenzialNonValideException, ControllerException {

        DAOFactory factory = DAOFactory.getDAOFactory();
        StudenteDAO studenteDAO = factory.createStudenteDAO();

        try {
            Studente trovato = studenteDAO.getStudenteByEmail(bean.getEmail());

            if (trovato == null) {
                throw new CredenzialNonValideException("Credenziali non valide.");
            }

            if (bean.getAuthProvider() == null) {
                // Login locale: verifica password
                if (!(trovato instanceof AutenticazioneLocale locale)) {
                    throw new CredenzialNonValideException(
                            "Questo account usa OAuth. Accedi con Google o Microsoft.");
                }
                if (!locale.passwordHash().equals(Hasher.codifica(bean.getPassword()))) {
                    throw new CredenzialNonValideException("Password errata.");
                }
            } else {
                // Login OAuth: verifica provider
                if (!(trovato instanceof AutenticazioneOAuth oauth)) {
                    throw new CredenzialNonValideException(
                            "Questo account usa email e password. Accedi localmente.");
                }
                if (oauth.ottieniProvider() != bean.getAuthProvider()) {
                    throw new CredenzialNonValideException(
                            "Questo account è registrato con: " + oauth.ottieniProvider());
                }
            }

            return creaSessioneStudente(trovato, factory);

        } catch (DAOException e) {
            throw new ControllerException("Errore durante il login studente.", e);
        }
    }

    // ── Login professore ──────────────────────────────────────────────────────

    public SessioneBean loginProfessore(ProfessoreBean bean)
            throws CredenzialNonValideException, ControllerException {

        DAOFactory factory = DAOFactory.getDAOFactory();
        ProfessoreDAO professoreDAO = factory.createProfessoreDAO();

        try {
            Professore trovato = professoreDAO.getProfessoreByEmail(bean.getEmail());

            if (trovato == null) {
                throw new CredenzialNonValideException("Credenziali non valide.");
            }

            if (bean.getAuthProvider() == null) {
                // Login locale
                if (!(trovato instanceof AutenticazioneLocale locale)) {
                    throw new CredenzialNonValideException(
                            "Questo account usa OAuth. Accedi con Google o Microsoft.");
                }
                if (!locale.passwordHash().equals(Hasher.codifica(bean.getPassword()))) {
                    throw new CredenzialNonValideException("Password errata.");
                }
            } else {
                // Login OAuth
                if (!(trovato instanceof AutenticazioneOAuth oauth)) {
                    throw new CredenzialNonValideException(
                            "Questo account usa email e password. Accedi localmente.");
                }
                if (oauth.ottieniProvider() != bean.getAuthProvider()) {
                    throw new CredenzialNonValideException(
                            "Questo account è registrato con: " + oauth.ottieniProvider());
                }
            }

            return creaSessioneProfessore(trovato, factory);

        } catch (DAOException e) {
            throw new ControllerException("Errore durante il login professore.", e);
        }
    }

    // ── Logout ────────────────────────────────────────────────────────────────

    public void logout(SessioneBean sessione) {
        SessionManager.getInstance().cancellaSessione(sessione.getId());
    }

    // ── Metodi privati ────────────────────────────────────────────────────────

    private SessioneBean creaSessioneStudente(Studente studente, DAOFactory factory)
            throws DAOException, ControllerException {

        PortafoglioDAO walletDAO = factory.createPortafoglioDAO();
        VirtualWallet wallet = walletDAO.getPortafoglioByEmail(studente.presentaEmail());

        if (wallet == null) {
            throw new ControllerException("Wallet non trovato per lo studente: dato corrotto.");
        }

        studente.assegnaWallet(wallet);
        Sessione sessione = SessionManager.getInstance().creaSessione(studente);

        StudenteBean studenteBean = new StudenteBean(
                studente.presentaEmail(),
                studente.presentaNome(),
                studente.presentaCognome()
        );

        if (studente.classeFrequentata() != null) {
            studenteBean.setNomeClasse(studente.classeFrequentata().nome());
            // IMPORTANTE: Imposta anche il budget della classe nello StudeneteBean
            studenteBean.setBudgetClasse(studente.classeFrequentata().budgetIniziale());
        }

        studenteBean.resetPassword();

        return new SessioneBean(sessione.getToken(), studenteBean);
    }
    private SessioneBean creaSessioneProfessore(Professore professore, DAOFactory factory) throws DAOException {

        Sessione sessione = SessionManager.getInstance().creaSessione(professore);

        ProfessoreBean professoreBean = new ProfessoreBean(
                professore.presentaEmail(),
                professore.presentaNome(),
                professore.presentaCognome()
        );

        // IMPORTANTE: Crea StudenteDAO PRIMA di SchoolClassDAO per garantire l'iniezione delle dipendenze
        factory.createStudenteDAO();

        SchoolClassDAO classDAO = factory.createSchoolClassDAO();
        SessioneBean sessioneBean = new SessioneBean(sessione.getToken(), professoreBean);

        // Converti SchoolClass in SchoolClassBean
        List<SchoolClass> classi = classDAO.getClassiByProfessore(professore);
        List<SchoolClassBean> classiBeans = new ArrayList<>();
        for (SchoolClass c : classi) {
            classiBeans.add(toBean(c));
        }
        sessioneBean.setListaClassi(classiBeans);

        return sessioneBean;
    }

    // ── Conversione model → bean ──────────────────────────────────────────────

    private SchoolClassBean toBean(SchoolClass c) {
        ProfessoreBean profBean = new ProfessoreBean(
                c.teacher().presentaEmail(),
                c.teacher().presentaNome(),
                c.teacher().presentaCognome());
        List<StudenteBean> studentiBeans = new ArrayList<>();
        if (c.studenti() != null) {
            for (Studente s : c.studenti()) {
                studentiBeans.add(new StudenteBean(
                        s.presentaEmail(), s.presentaNome(), s.presentaCognome()));
            }
        }
        return new SchoolClassBean(c.nome(), profBean, c.budgetIniziale(), studentiBeans);
    }
}

package org.project.control;

import org.project.dao.posizioni.WalletPositionDAO;
import org.project.dao.transazioni.TransactionDAO;
import org.project.dao.wallets.PortafoglioDAO;
import org.project.exceptions.ControllerException;
import org.project.exceptions.DAOException;
import org.project.ing.enumerations.TipoTransazione;
import org.project.ing.persistenza.DAOFactory;
import org.project.ing.service.StockService;
import org.project.model.*;
import org.project.view.bean.SessioneBean;
import org.project.view.bean.StockBean;
import org.project.view.bean.TransactionBean;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;

/**
 * Controller applicativo unificato per il caso d'uso "Manage Stock".
 *
 * Responsabilità:
 *  - fornire alla view i dati di uno stock (prezzo attuale, variazioni, ecc.)
 *    tramite StockService, che gestisce l'observer su Yahoo Finance API
 *  - creare una Transaction PENDING quando lo studente decide di acquistare
 *  - confermare o annullare l'ordine con verifica budget e persistenza
 *
 * Sostituisce MercatoAppController + OrdineAppController, che erano
 * artificialmente separati a fronte di un unico caso d'uso nel diagramma.
 *
 * Stateless (GRASP Controller): ogni chiamata è indipendente; lo stato
 * della transazione pending vive nella Sessione (model), non qui.
 */
public class ManageStockAppController {

    private static final int TIMEOUT_MINUTI = 5;

    // ── Consultazione mercato ─────────────────────────────────────────────────

    /**
     * Recupera i dati aggiornati di uno stock dato il suo simbolo.
     * Lo StockService garantisce unicità in memoria e polling automatico.
     *
     * @param simbolo es. "AAPL", "TSLA"
     * @return StockBean pronto per la view
     */
    public StockBean cercaStock(String simbolo) throws ControllerException {
        try {
            Stock stock = StockService.getInstance().ottieniOCreaStock(simbolo);
            if (stock == null) {
                throw new ControllerException(
                        "Stock \"" + simbolo + "\" non trovato. Verifica il simbolo e riprova.");
            }
            return toBean(stock);
        } catch (ControllerException e) {
            throw e;
        } catch (Exception e) {
            throw new ControllerException(e.getMessage(), e);
        }
    }

    /**
     * Avvia un ordine di acquisto: crea una Transaction PENDING e la salva nella sessione.
     * Lo studente ha {@value #TIMEOUT_MINUTI} minuti per confermare.
     *
     * @param sessione sessione corrente (contiene wallet e studente)
     * @param simbolo  simbolo dello stock da acquistare
     * @return TransactionBean con stato PENDING da mostrare alla view
     */
    public TransactionBean avviaOrdineAcquisto(SessioneBean sessione, String simbolo)
            throws ControllerException {

        Sessione sessioneModel = SessionManager.getInstance().ottieniSessione(sessione.getId());
        if (sessioneModel == null)
            throw new ControllerException("Sessione non valida o scaduta.");

        Studente studente = sessioneModel.getStudenteCorrente();
        if (studente == null)
            throw new ControllerException("Nessuno studente associato alla sessione.");

        VirtualWallet wallet = sessioneModel.getWalletCorrente();
        if (wallet == null)
            throw new ControllerException("Wallet non trovato per lo studente.");

        try {
            Stock stock = StockService.getInstance().ottieniOCreaStock(simbolo);

            // quantita=1 come placeholder — verrà aggiornata alla conferma
            Transaction transazione = new Transaction(
                    stock, TipoTransazione.BUY, 1, stock.prezzoAttuale());

            sessioneModel.setTransazionePending(transazione);
            sessioneModel.setStockCorrente(stock);

            return toTransactionBean(transazione);

        } catch (Exception e) {
            throw new ControllerException("Errore nell'avvio dell'ordine per: " + simbolo, e);
        }
    }

    // ── Conferma / annullamento ordine ────────────────────────────────────────

    /**
     * Conferma l'ordine pending con la quantità scelta dallo studente.
     *
     * Verifica:
     *  1. Sessione e transazione pending presenti
     *  2. Timeout non superato
     *  3. Saldo sufficiente
     *
     * Delega la logica di acquisto a VirtualWallet (Expert Pattern),
     * poi persiste transazione, posizione e wallet via DAO.
     *
     * @param sessione       sessione corrente
     * @param quantitaScelta quantità di azioni scelta dallo studente (> 0)
     * @return TransactionBean con stato DONE
     */
    public TransactionBean confermaAcquisto(SessioneBean sessione, double quantitaScelta)
            throws ControllerException {

        Sessione sessioneModel = SessionManager.getInstance().ottieniSessione(sessione.getId());
        if (sessioneModel == null)
            throw new ControllerException("Sessione non valida o scaduta.");

        Transaction transazione = sessioneModel.getTransazionePending();
        if (transazione == null)
            throw new ControllerException("Nessun ordine pending trovato. Riprova.");

        // 1. Verifica timeout passivamente al momento della conferma
        long minutiTrascorsi = ChronoUnit.MINUTES.between(transazione.quando(), LocalDateTime.now());
        if (minutiTrascorsi > TIMEOUT_MINUTI) {
            sessioneModel.setTransazionePending(null);
            throw new ControllerException(
                    "Il tempo per confermare l'ordine è scaduto (limite: "
                            + TIMEOUT_MINUTI + " minuti). Riprova.");
        }

        // 2. Aggiorna la quantità con la scelta finale dello studente
        transazione.impostaQuantita(quantitaScelta);

        VirtualWallet wallet = sessioneModel.getWalletCorrente();
        if (wallet == null)
            throw new ControllerException("Wallet non trovato per lo studente.");

        // 3. Verifica saldo sufficiente
        if (wallet.saldoDisponibile() < transazione.importoTotale())
            throw new ControllerException(
                    "Saldo insufficiente. Disponibile: " + wallet.saldoDisponibile()
                            + ", richiesto: " + transazione.importoTotale());

        DAOFactory factory = DAOFactory.getDAOFactory();
        TransactionDAO transactionDAO = factory.createTransactionDAO();
        WalletPositionDAO posizioneDAO = factory.createWalletPositionDAO();
        PortafoglioDAO walletDAO = factory.createPortafoglioDAO();

        try {
            // 4. Delega tutta la logica al wallet (Expert Pattern)
            boolean posizioneEsisteva = wallet.trovaPosizione(transazione.stock()) != null;
            WalletPosition posizione = wallet.eseguiAcquisto(
                    transazione.stock(), quantitaScelta, transazione.prezzoAlMomento());

            // 5. Completa la transazione e aggiungila al wallet
            transazione.completaTransazione();
            wallet.aggiungiTransazione(transazione);

            // 6. Persisti
            String emailStudente = wallet.proprietario().presentaEmail();
            transactionDAO.salvaTransazione(emailStudente, transazione);
            if (posizioneEsisteva) {
                posizioneDAO.aggiornaPosizione(emailStudente, posizione);
            } else {
                posizioneDAO.salvaPosizione(emailStudente, posizione);
            }
            walletDAO.aggiornaPortafoglio(wallet);

            // 7. Pulisci la pending dalla sessione
            sessioneModel.setTransazionePending(null);

            return toTransactionBean(transazione);

        } catch (DAOException e) {
            throw new ControllerException("Errore durante il salvataggio dell'ordine.", e);
        }
    }

    /**
     * Annulla l'ordine pending (lo studente clicca "annulla" prima del timeout).
     */
    public void annullaOrdine(SessioneBean sessione) throws ControllerException {
        Sessione sessioneModel = SessionManager.getInstance().ottieniSessione(sessione.getId());
        if (sessioneModel == null)
            throw new ControllerException("Sessione non valida o scaduta.");
        sessioneModel.setTransazionePending(null);
        sessioneModel.setStockCorrente(null);
    }

    // ── Conversioni model → bean ──────────────────────────────────────────────

    private StockBean toBean(Stock s) {
        StockBean bean = new StockBean(
                s.simbolo(), s.nomeAzienda(), s.settore(), s.prezzoAttuale());
        bean.setVariazioneGiornaliera(s.variazioneGiornaliera());
        bean.setVariazioneSettimanale(s.variazioneSettimanale());
        bean.setMarketCap(s.marketCap());
        bean.setVolumeSettimanale(s.volumeSettimanale());
        return bean;
    }

    private TransactionBean toTransactionBean(Transaction t) {
        StockBean stockBean = new StockBean(
                t.stock().simbolo(), t.stock().nomeAzienda(),
                t.stock().settore(), t.stock().prezzoAttuale());
        return new TransactionBean(
                stockBean, t.tipo(), t.stato(),
                t.quantita(), t.prezzoAlMomento(),
                t.importoTotale(), t.quando());
    }

    /**
     * Converte un VirtualWallet in PortafoglioBean per la visualizzazione nella view.
     * Utile per aggiornare il PortafoglioBean nel Navigator dopo una transazione.
     *
     * @param wallet il VirtualWallet del corrente studente
     * @return PortafoglioBean con posizioni e transazioni convertite in bean
     */
    public PortafoglioBean convertiWalletInBean(VirtualWallet wallet) {
        if (wallet == null) return null;

        List<WalletPositionBean> posizioniBeans = new ArrayList<>();
        if (wallet.posizioni() != null) {
            for (WalletPosition p : wallet.posizioni()) {
                StockBean stockBean = new StockBean();
                stockBean.setSimbolo(p.stock().simbolo());
                stockBean.setNomeAzienda(p.stock().nomeAzienda());

                WalletPositionBean wpBean = new WalletPositionBean();
                wpBean.setStock(stockBean);
                wpBean.setQuantita(p.quantita());
                wpBean.setPrezzoMedioAcquisto(p.prezzoMedioAcquisto());
                wpBean.setValoreAttuale(p.valoreAttuale());
                double spesaIniziale = p.quantita() * p.prezzoMedioAcquisto();
                wpBean.setProfittoPerdita(p.valoreAttuale() - spesaIniziale);

                posizioniBeans.add(wpBean);
            }
        }

        List<TransactionBean> transazioniBeans = new ArrayList<>();
        if (wallet.transazioni() != null) {
            for (Transaction t : wallet.transazioni()) {
                StockBean stockBean = new StockBean();
                stockBean.setSimbolo(t.stock().simbolo());

                TransactionBean txBean = new TransactionBean();
                txBean.setStock(stockBean);
                txBean.setTipo(t.tipo());
                txBean.setImportoTotale(t.importoTotale());
                txBean.setStato(t.stato());

                transazioniBeans.add(txBean);
            }
        }

        return new PortafoglioBean(
                wallet.saldoDisponibile(),
                wallet.calcolaTotalePortafoglio(),
                posizioniBeans,
                transazioniBeans
        );
    }
}

package org.project.control;

import org.project.dao.posizioni.WalletPositionDAO;
import org.project.dao.transazioni.TransactionDAO;
import org.project.dao.wallets.PortafoglioDAO;
import org.project.exceptions.ControllerException;
import org.project.exceptions.DAOException;
import org.project.ing.enumerations.TipoTransazione;
import org.project.ing.persistenza.DAOFactory;
import org.project.ing.service.StockService;
import org.project.model.*;
import org.project.view.bean.*;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;

/**
 * Controller applicativo unificato per il caso d'uso "Manage Stock".
 *
 * Responsabilità:
 *  - fornire alla view i dati di uno stock (prezzo attuale, variazioni, ecc.)
 *    tramite StockService, che gestisce l'observer su Yahoo Finance API
 *  - creare una Transaction PENDING quando lo studente decide di acquistare
 *  - confermare o annullare l'ordine con verifica budget e persistenza
 *
 * Sostituisce MercatoAppController + OrdineAppController, che erano
 * artificialmente separati a fronte di un unico caso d'uso nel diagramma.
 *
 * Stateless (GRASP Controller): ogni chiamata è indipendente; lo stato
 * della transazione pending vive nella Sessione (model), non qui.
 */
public class ManageStockAppController {

    private static final int TIMEOUT_MINUTI = 5;

    // ── Consultazione mercato ─────────────────────────────────────────────────

    /**
     * Recupera i dati aggiornati di uno stock dato il suo simbolo.
     * Lo StockService garantisce unicità in memoria e polling automatico.
     *
     * @param simbolo es. "AAPL", "TSLA"
     * @return StockBean pronto per la view
     */
    public StockBean cercaStock(String simbolo) throws ControllerException {
        try {
            Stock stock = StockService.getInstance().ottieniOCreaStock(simbolo);
            if (stock == null) {
                throw new ControllerException(
                        "Stock \"" + simbolo + "\" non trovato. Verifica il simbolo e riprova.");
            }
            return toBean(stock);
        } catch (ControllerException e) {
            throw e;
        } catch (Exception e) {
            throw new ControllerException(e.getMessage(), e);
        }
    }

    /**
     * Avvia un ordine di acquisto: crea una Transaction PENDING e la salva nella sessione.
     * Lo studente ha {@value #TIMEOUT_MINUTI} minuti per confermare.
     *
     * @param sessione sessione corrente (contiene wallet e studente)
     * @param simbolo  simbolo dello stock da acquistare
     * @return TransactionBean con stato PENDING da mostrare alla view
     */
    public TransactionBean avviaOrdineAcquisto(SessioneBean sessione, String simbolo)
            throws ControllerException {

        Sessione sessioneModel = SessionManager.getInstance().ottieniSessione(sessione.getId());
        if (sessioneModel == null)
            throw new ControllerException("Sessione non valida o scaduta.");

        Studente studente = sessioneModel.getStudenteCorrente();
        if (studente == null)
            throw new ControllerException("Nessuno studente associato alla sessione.");

        VirtualWallet wallet = sessioneModel.getWalletCorrente();
        if (wallet == null)
            throw new ControllerException("Wallet non trovato per lo studente.");

        try {
            Stock stock = StockService.getInstance().ottieniOCreaStock(simbolo);

            // quantita=1 come placeholder — verrà aggiornata alla conferma
            Transaction transazione = new Transaction(
                    stock, TipoTransazione.BUY, 1, stock.prezzoAttuale());

            sessioneModel.setTransazionePending(transazione);
            sessioneModel.setStockCorrente(stock);

            return toTransactionBean(transazione);

        } catch (Exception e) {
            throw new ControllerException("Errore nell'avvio dell'ordine per: " + simbolo, e);
        }
    }

    // ── Conferma / annullamento ordine ────────────────────────────────────────

    /**
     * Conferma l'ordine pending con la quantità scelta dallo studente.
     *
     * Verifica:
     *  1. Sessione e transazione pending presenti
     *  2. Timeout non superato
     *  3. Saldo sufficiente
     *
     * Delega la logica di acquisto a VirtualWallet (Expert Pattern),
     * poi persiste transazione, posizione e wallet via DAO.
     *
     * @param sessione       sessione corrente
     * @param quantitaScelta quantità di azioni scelta dallo studente (> 0)
     * @return TransactionBean con stato DONE
     */
    public TransactionBean confermaAcquisto(SessioneBean sessione, double quantitaScelta)
            throws ControllerException {

        Sessione sessioneModel = SessionManager.getInstance().ottieniSessione(sessione.getId());
        if (sessioneModel == null)
            throw new ControllerException("Sessione non valida o scaduta.");

        Transaction transazione = sessioneModel.getTransazionePending();
        if (transazione == null)
            throw new ControllerException("Nessun ordine pending trovato. Riprova.");

        // 1. Verifica timeout passivamente al momento della conferma
        long minutiTrascorsi = ChronoUnit.MINUTES.between(transazione.quando(), LocalDateTime.now());
        if (minutiTrascorsi > TIMEOUT_MINUTI) {
            sessioneModel.setTransazionePending(null);
            throw new ControllerException(
                    "Il tempo per confermare l'ordine è scaduto (limite: "
                            + TIMEOUT_MINUTI + " minuti). Riprova.");
        }

        // 2. Aggiorna la quantità con la scelta finale dello studente
        transazione.impostaQuantita(quantitaScelta);

        VirtualWallet wallet = sessioneModel.getWalletCorrente();
        if (wallet == null)
            throw new ControllerException("Wallet non trovato per lo studente.");

        // 3. Verifica saldo sufficiente
        if (wallet.saldoDisponibile() < transazione.importoTotale())
            throw new ControllerException(
                    "Saldo insufficiente. Disponibile: " + wallet.saldoDisponibile()
                            + ", richiesto: " + transazione.importoTotale());

        DAOFactory factory = DAOFactory.getDAOFactory();
        TransactionDAO transactionDAO = factory.createTransactionDAO();
        WalletPositionDAO posizioneDAO = factory.createWalletPositionDAO();
        PortafoglioDAO walletDAO = factory.createPortafoglioDAO();

        try {
            // 4. Delega tutta la logica al wallet (Expert Pattern)
            boolean posizioneEsisteva = wallet.trovaPosizione(transazione.stock()) != null;
            WalletPosition posizione = wallet.eseguiAcquisto(
                    transazione.stock(), quantitaScelta, transazione.prezzoAlMomento());

            // 5. Completa la transazione e aggiungila al wallet
            transazione.completaTransazione();
            wallet.aggiungiTransazione(transazione);

            // 6. Persisti
            String emailStudente = wallet.proprietario().presentaEmail();
            transactionDAO.salvaTransazione(emailStudente, transazione);
            if (posizioneEsisteva) {
                posizioneDAO.aggiornaPosizione(emailStudente, posizione);
            } else {
                posizioneDAO.salvaPosizione(emailStudente, posizione);
            }
            walletDAO.aggiornaPortafoglio(wallet);

            // 7. Pulisci la pending dalla sessione
            sessioneModel.setTransazionePending(null);

            return toTransactionBean(transazione);

        } catch (DAOException e) {
            throw new ControllerException("Errore durante il salvataggio dell'ordine.", e);
        }
    }

    /**
     * Annulla l'ordine pending (lo studente clicca "annulla" prima del timeout).
     */
    public void annullaOrdine(SessioneBean sessione) throws ControllerException {
        Sessione sessioneModel = SessionManager.getInstance().ottieniSessione(sessione.getId());
        if (sessioneModel == null)
            throw new ControllerException("Sessione non valida o scaduta.");
        sessioneModel.setTransazionePending(null);
        sessioneModel.setStockCorrente(null);
    }

    // ── Conversioni model → bean ──────────────────────────────────────────────

    private StockBean toBean(Stock s) {
        StockBean bean = new StockBean(
                s.simbolo(), s.nomeAzienda(), s.settore(), s.prezzoAttuale());
        bean.setVariazioneGiornaliera(s.variazioneGiornaliera());
        bean.setVariazioneSettimanale(s.variazioneSettimanale());
        bean.setMarketCap(s.marketCap());
        bean.setVolumeSettimanale(s.volumeSettimanale());
        return bean;
    }

    private TransactionBean toTransactionBean(Transaction t) {
        StockBean stockBean = new StockBean(
                t.stock().simbolo(), t.stock().nomeAzienda(),
                t.stock().settore(), t.stock().prezzoAttuale());
        return new TransactionBean(
                stockBean, t.tipo(), t.stato(),
                t.quantita(), t.prezzoAlMomento(),
                t.importoTotale(), t.quando());
    }

    /**
     * Converte un VirtualWallet in PortafoglioBean per la visualizzazione nella view.
     * Utile per aggiornare il PortafoglioBean nel Navigator dopo una transazione.
     *
     * @param wallet il VirtualWallet del corrente studente
     * @return PortafoglioBean con posizioni e transazioni convertite in bean
     */
    public PortafoglioBean convertiWalletInBean(VirtualWallet wallet) {
        if (wallet == null) return null;

        List<WalletPositionBean> posizioniBeans = new ArrayList<>();
        if (wallet.posizioni() != null) {
            for (WalletPosition p : wallet.posizioni()) {
                StockBean stockBean = new StockBean();
                stockBean.setSimbolo(p.stock().simbolo());
                stockBean.setNomeAzienda(p.stock().nomeAzienda());

                WalletPositionBean wpBean = new WalletPositionBean();
                wpBean.setStock(stockBean);
                wpBean.setQuantita(p.quantita());
                wpBean.setPrezzoMedioAcquisto(p.prezzoMedioAcquisto());
                wpBean.setValoreAttuale(p.valoreAttuale());
                double spesaIniziale = p.quantita() * p.prezzoMedioAcquisto();
                wpBean.setProfittoPerdita(p.valoreAttuale() - spesaIniziale);

                posizioniBeans.add(wpBean);
            }
        }

        List<TransactionBean> transazioniBeans = new ArrayList<>();
        if (wallet.transazioni() != null) {
            for (Transaction t : wallet.transazioni()) {
                StockBean stockBean = new StockBean();
                stockBean.setSimbolo(t.stock().simbolo());

                TransactionBean txBean = new TransactionBean();
                txBean.setStock(stockBean);
                txBean.setTipo(t.tipo());
                txBean.setImportoTotale(t.importoTotale());
                txBean.setStato(t.stato());

                transazioniBeans.add(txBean);
            }
        }

        return new PortafoglioBean(
                wallet.saldoDisponibile(),
                wallet.calcolaTotalePortafoglio(),
                posizioniBeans,
                transazioniBeans
        );
    }
}

package org.project.view;

import javafx.application.Platform;
import javafx.fxml.FXML;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import org.project.ing.observer.StockObserver;
import org.project.ing.service.StockService;
import org.project.model.Stock;
import org.project.view.bean.*;

import java.text.NumberFormat;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.*;

/**
 * Implementazione GUI (JavaFX) di ManageWalletsGraphicController.
 * Gestisce via panel show/hide tutti i sotto-flussi del caso d'uso:
 * – Mercato (panelDettaglio + griglia stock)
 * – Conferma ordine (panelConfermaOrdine)
 * – Portafoglio proprio / esterno (panelPortafoglio)
 * – Storico transazioni (panelStorico)
 * Tutti i pannelli centrali partono hidden/unmanaged e vengono attivati
 * dal controller nei metodi start*().
 * FXML: ManageWallets.fxml (fx:controller = org.project.view.ManageWalletsGraphicControllerGUI)
 */
public class ManageWalletsGraphicControllerGUI
        extends ManageWalletsGraphicController
        implements StockObserver {

    private static final String LABEL_TOTALE_VUOTO = "Totale: —";
    private static final String CSS_TESTO_SECONDARIO = "testo-secondario";
    private static final String CSS_TESTO_GRIGIO = "-fx-text-fill:#555555;";
    private static final String FORMATO_PREZZO = "$ %.2f";
    private static final String FORMATO_VARIAZIONE = "%+.2f%%";
    private static final String TAG_POSITIVO = "tag-positivo";
    private static final String TAG_NEGATIVO = "tag-negativo";

    // ── FXML Sidebar ──────────────────────────────────────────────────────────
    @FXML private Label            lblRuoloSidebar;
    @FXML private VBox             boxInfoUtente;
    @FXML private Label            lblNomeUtente;
    @FXML private Label            lblSaldoSidebar;
    @FXML private VBox             boxNavWallet;

    // ── FXML Header ───────────────────────────────────────────────────────────
    @FXML private Label            lblSottotitoloMercato;
    @FXML private TextField        txtRicerca;

    // ── FXML Feedback ─────────────────────────────────────────────────────────
    @FXML private Label            lblMessaggio;
    @FXML private HBox             boxCaricamento;

    // ── FXML Pannello dettaglio stock ─────────────────────────────────────────
    @FXML private VBox             panelDettaglio;
    @FXML private Label            lblDetSimbolo;
    @FXML private Label            lblDetNome;
    @FXML private Label            lblDetSettore;
    @FXML private Label            lblDetPrezzo;
    @FXML private Label            lblDetVariazione;
    @FXML private Label            lblDetVarSettimanale;
    @FXML private Label            lblDetMarketCap;
    @FXML private Label            lblDetVolume;
    @FXML private Label            lblDetAggiornamento;
    @FXML private VBox             boxAzioneAcquisto;
    @FXML private Label            lblSaldoCheck;
    @FXML private Button           btnCompra;
    @FXML private VBox             boxSolaLettura;

    // ── FXML Pannello conferma ordine ─────────────────────────────────────────
    @FXML private VBox             panelConfermaOrdine;
    @FXML private Label            lblOrdineStock;
    @FXML private Label            lblOrdinePrezzo;
    @FXML private Label            lblOrdineSaldo;
    @FXML private TextField        txtQuantita;
    @FXML private Label            lblOrdineTotale;
    @FXML private Button           btnConfermaOrdine;

    // ── FXML Pannello portafoglio ─────────────────────────────────────────────
    @FXML private VBox             panelPortafoglio;
    @FXML private Label            lblTitoloPortafoglio;
    @FXML private Label            lblSaldoPortafoglio;
    @FXML private Label            lblTotalePortafoglio;
    @FXML private VBox             vboxPosizioni;
    @FXML private Button           btnPortafoglioStorico;
    @FXML private Button           btnPortafoglioTorna;

    // ── FXML Pannello storico transazioni ─────────────────────────────────────
    @FXML private VBox             panelStorico;
    @FXML private Label            lblTitoloStorico;
    @FXML private VBox             vboxStorico;

    // ── FXML Griglia mercato ──────────────────────────────────────────────────
    @FXML private FlowPane         flowStocks;
    @FXML private Label            lblTitoloGriglia;
    @FXML private Label            lblContatore;
    @FXML private Label            lblNessunoStock;

    private Parent  view;
    private String  simboloCorrente;
    private boolean portafoglioEsterno = false;

    private final Map<String, Label> prezziInGriglia = new HashMap<>();
    private final Map<String, Stock> subjectMap = new HashMap<>();

    private static final NumberFormat  VALUTA = NumberFormat.getCurrencyInstance(Locale.ITALY);
    private static final DateTimeFormatter FMT = DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm:ss");

    // ── Setter / Getter ───────────────────────────────────────────────────────

    public void setView(Parent view)              { this.view = view; }
    public Parent getView()                       { return view; }
    public void setGuiNavigator(NavigatorGUI nav) { super.setNavigator(nav); }

    // ── start() — schermata mercato ───────────────────────────────────────────

    @Override
    public void start() {
        nascondiTuttiIPannelli();
        nascondiMessaggio();
        portafoglioEsterno = false;

        SessioneBean sessione = navigator.getSessione();
        if (isStudente) {
            String nome = (sessione != null && sessione.getStudente() != null)
                    ? sessione.getStudente().getNome() : "—";
            lblNomeUtente.setText(nome);
            lblRuoloSidebar.setText("Manage Wallets · Studente");
            boxInfoUtente.getStyleClass().removeAll("card-professore");
            boxInfoUtente.getStyleClass().add("card-studente");
            lblSottotitoloMercato.setText("Esplora il mercato e investi nei tuoi titoli preferiti");

            PortafoglioBean pf = navigator.getPortafoglio();
            lblSaldoSidebar.setText(pf != null
                    ? "Saldo: " + VALUTA.format(pf.getSaldoDisponibile()) : "");

            if (boxNavWallet != null) {
                boxNavWallet.setVisible(true);
                boxNavWallet.setManaged(true);
            }
        } else {
            String nome = (sessione != null && sessione.getProfessore() != null)
                    ? "Prof. " + sessione.getProfessore().getNome() : "—";
            lblNomeUtente.setText(nome);
            lblRuoloSidebar.setText("Manage Wallets · Professore");
            boxInfoUtente.getStyleClass().removeAll("card-studente");
            boxInfoUtente.getStyleClass().add("card-professore");
            lblSaldoSidebar.setText("Visualizzazione in sola lettura");
            lblSottotitoloMercato.setText("Monitora gli andamenti del mercato");

            if (boxNavWallet != null) {
                boxNavWallet.setVisible(false);
                boxNavWallet.setManaged(false);
            }
        }

        aggiornaGriglia(navigator.getListaStock());
        StockService.getInstance().avviaAggiornamentoAutomatico();
    }

    // ── startConfermaOrdine() ─────────────────────────────────────────────────

    @Override
    public void startConfermaOrdine() {
        TransactionBean t = navigator.getTransazionePending();
        if (t == null) {
            mostraErrore("Nessun ordine da confermare.");
            return;
        }

        nascondiTuttiIPannelli();
        nascondiMessaggio();

        lblOrdineStock.setText(t.getStock().getSimbolo() + " — " + t.getStock().getNomeAzienda());
        lblOrdinePrezzo.setText(String.format("Prezzo unitario: " + FORMATO_PREZZO, t.getPrezzoAlMomento()));

        PortafoglioBean pf = navigator.getPortafoglio();
        lblOrdineSaldo.setText(pf != null
                ? "Saldo disponibile: " + VALUTA.format(pf.getSaldoDisponibile()) : "");

        resettaCampiOrdine();

        txtQuantita.textProperty().addListener((obs, oldV, newV) ->
                aggiornaTotaleOrdine(newV, t, pf)
        );

        panelConfermaOrdine.setVisible(true);
        panelConfermaOrdine.setManaged(true);
    }

    private void resettaCampiOrdine() {
        txtQuantita.clear();
        lblOrdineTotale.setText(LABEL_TOTALE_VUOTO);
        if (btnConfermaOrdine != null) btnConfermaOrdine.setDisable(true);
    }

    private void aggiornaTotaleOrdine(String quantitaInserita, TransactionBean t, PortafoglioBean pf) {
        try {
            double q = Double.parseDouble(quantitaInserita.replace(",", "."));
            if (q > 0) {
                double totale = q * t.getPrezzoAlMomento();
                lblOrdineTotale.setText("Totale: " + VALUTA.format(totale));
                boolean saldoOk = pf == null || pf.getSaldoDisponibile() >= totale;

                if (btnConfermaOrdine != null) btnConfermaOrdine.setDisable(!saldoOk);

                lblOrdineTotale.setStyle(saldoOk
                        ? "-fx-text-fill:#2e7d32; -fx-font-weight:bold;"
                        : "-fx-text-fill:#d32f2f; -fx-font-weight:bold;");
            } else {
                resettaCampiOrdine();
            }
        } catch (NumberFormatException e) {
            resettaCampiOrdine();
        }
    }

    // ── startPortafoglio() ────────────────────────────────────────────────────

    @Override
    public void startPortafoglio() {
        nascondiTuttiIPannelli();
        nascondiMessaggio();
        portafoglioEsterno = false;
        eseguiCaricaPortafoglio(navigator.getStudenteTarget().getEmail());
    }

    // ── startStorico() ────────────────────────────────────────────────────────

    @Override
    public void startStorico() {
        nascondiTuttiIPannelli();
        nascondiMessaggio();
        eseguiCaricaStorico(navigator.getStudenteTarget().getEmail());
    }

    // ── startWalletEsterno() ──────────────────────────────────────────────────

    @Override
    public void startWalletEsterno(StudenteBean studenteTarget) {
        nascondiTuttiIPannelli();
        nascondiMessaggio();
        portafoglioEsterno = true;
        eseguiCaricaPortafoglio(studenteTarget.getEmail());
    }

    // ── mostraPortafoglio() ───────────────────────────────────────────────────

    @Override
    protected void mostraPortafoglio(PortafoglioBean pf, boolean isProprietario) {
        Platform.runLater(() -> {
            impostaTitoloPortafoglio(isProprietario);

            if (pf == null) {
                mostraPortafoglioVuoto();
            } else {
                popolaDatiPortafoglio(pf);
            }

            impostaPulsantiNavigazionePortafoglio(isProprietario);

            panelPortafoglio.setVisible(true);
            panelPortafoglio.setManaged(true);
        });
    }

    private void impostaTitoloPortafoglio(boolean isProprietario) {
        lblTitoloPortafoglio.setText(isProprietario
                ? " Il Tuo Portafoglio"
                : " Portafoglio (sola lettura)");
    }

    private void mostraPortafoglioVuoto() {
        lblSaldoPortafoglio.setText("Nessun dato disponibile.");
        lblTotalePortafoglio.setText("");
        vboxPosizioni.getChildren().clear();
    }

    private void popolaDatiPortafoglio(PortafoglioBean pf) {
        lblSaldoPortafoglio.setText(" Saldo disponibile: " + VALUTA.format(pf.getSaldoDisponibile()));
        lblTotalePortafoglio.setText(" Valore totale wallet: " + VALUTA.format(pf.getValoreTotalePortafoglio()));

        vboxPosizioni.getChildren().clear();

        if (pf.getPosizioni() == null || pf.getPosizioni().isEmpty()) {
            Label nessuna = new Label("Nessuna posizione aperta.");
            nessuna.getStyleClass().add(CSS_TESTO_SECONDARIO);
            vboxPosizioni.getChildren().add(nessuna);
        } else {
            HBox header = creaRigaIntestazione("Simbolo", "Azienda", "Quantità", "Pr.Medio", "Val.Att.", "P/L");
            vboxPosizioni.getChildren().add(header);

            for (WalletPositionBean p : pf.getPosizioni()) {
                vboxPosizioni.getChildren().add(creaRigaPosizione(p));
            }
        }
    }

    private void impostaPulsantiNavigazionePortafoglio(boolean isProprietario) {
        if (btnPortafoglioStorico != null) {
            btnPortafoglioStorico.setVisible(isProprietario);
            btnPortafoglioStorico.setManaged(isProprietario);
        }

        if (btnPortafoglioTorna != null) {
            btnPortafoglioTorna.setVisible(isProprietario);
            btnPortafoglioTorna.setManaged(isProprietario);
        }
    }

    // ── mostraStorico() ───────────────────────────────────────────────────────

    @Override
    protected void mostraStorico(List<TransactionBean> storico, String emailTarget) {
        Platform.runLater(() -> {
            lblTitoloStorico.setText(emailTarget == null
                    ? " Storico Transazioni"
                    : " Storico Transazioni (sola lettura)");

            vboxStorico.getChildren().clear();

            if (storico == null || storico.isEmpty()) {
                Label nessuna = new Label("Nessuna transazione registrata.");
                nessuna.getStyleClass().add(CSS_TESTO_SECONDARIO);
                vboxStorico.getChildren().add(nessuna);
            } else {
                HBox header = creaRigaIntestazione("Data", "Simbolo", "Tipo", "Quantità", "Importo", "Stato");
                vboxStorico.getChildren().add(header);
                for (TransactionBean t : storico) {
                    vboxStorico.getChildren().add(creaRigaTransazione(t));
                }
            }

            panelStorico.setVisible(true);
            panelStorico.setManaged(true);
        });
    }

    // ── StockObserver ─────────────────────────────────────────────────────────

    @Override
    public void aggiornamento() {
        Platform.runLater(() -> {

            for (Map.Entry<String, Stock> entry : subjectMap.entrySet()) {
                double nuovoPrezzo = entry.getValue().getState(); // getState() GoF
                Label lbl = prezziInGriglia.get(entry.getKey());
                if (lbl != null)
                    lbl.setText(String.format(FORMATO_PREZZO, nuovoPrezzo));
            }

            // Aggiorna il pannello dettaglio se è aperto
            if (simboloCorrente != null) {
                Stock s = subjectMap.get(simboloCorrente);
                if (s != null) {
                    lblDetPrezzo.setText(String.format(FORMATO_PREZZO, s.getState()));
                    lblDetVariazione.setText(String.format(FORMATO_VARIAZIONE,
                            s.variazioneGiornaliera()));
                    lblDetAggiornamento.setText("Aggiornato: "
                            + LocalDateTime.now(ZoneId.systemDefault()).format(FMT));

                    lblDetVariazione.getStyleClass().removeAll(TAG_POSITIVO, TAG_NEGATIVO);
                    lblDetVariazione.getStyleClass().add(
                            s.variazioneGiornaliera() >= 0 ? TAG_POSITIVO : TAG_NEGATIVO);
                }
            }
        });
    }

    // ── Griglia stock ─────────────────────────────────────────────────────────

    private void aggiornaGriglia(List<StockBean> lista) {
        flowStocks.getChildren().clear();
        prezziInGriglia.clear();

        if (lista == null || lista.isEmpty()) {
            lblNessunoStock.setVisible(true);
            lblNessunoStock.setManaged(true);
            lblContatore.setText("");
            return;
        }

        lblNessunoStock.setVisible(false);
        lblNessunoStock.setManaged(false);
        lblContatore.setText("(" + lista.size() + " titoli)");

        for (StockBean s : lista) {
            flowStocks.getChildren().add(creaCardStock(s));
            Stock sm = StockService.getInstance().trovaStock(s.getSimbolo());
            if (sm != null) {
                sm.aggiungiObserver(this);
                subjectMap.put(s.getSimbolo(), sm);
            }
        }
    }

    private VBox creaCardStock(StockBean s) {
        VBox card = new VBox(10);
        card.setPrefWidth(260);
        card.getStyleClass().add("card-stock");
        card.setStyle(card.getStyle() + "; -fx-cursor:hand;");

        HBox top = new HBox(8);
        top.setAlignment(Pos.CENTER_LEFT);
        Label lblSim = new Label(s.getSimbolo());
        lblSim.getStyleClass().add("simbolo-stock");

        double variazione = s.getVariazioneGiornaliera();
        Label lblVar = new Label(String.format(FORMATO_VARIAZIONE, variazione));
        lblVar.getStyleClass().add(variazione >= 0 ? TAG_POSITIVO : TAG_NEGATIVO);

        HBox spacer = new HBox(); HBox.setHgrow(spacer, Priority.ALWAYS);
        top.getChildren().addAll(lblSim, spacer, lblVar);

        Label lblNome   = new Label(tronca(s.getNomeAzienda(), 28));
        lblNome.getStyleClass().add(CSS_TESTO_SECONDARIO);
        Label lblPrezzo = new Label(String.format(FORMATO_PREZZO, s.getPrezzoAttuale()));
        lblPrezzo.setStyle("-fx-font-size:20px; -fx-font-weight:bold; -fx-text-fill:#1a1a2e;");
        prezziInGriglia.put(s.getSimbolo(), lblPrezzo);
        Label lblSett = new Label(s.getSettore());
        lblSett.getStyleClass().add(CSS_TESTO_SECONDARIO);
        lblSett.setStyle(lblSett.getStyle() + "; -fx-font-size:10px;");
        card.getChildren().addAll(top, lblNome, lblPrezzo, lblSett);

        card.setOnMouseClicked(e -> {
            nascondiConfermaOrdine();
            nascondiPortafoglio();
            nascondiStorico();
            simboloCorrente = s.getSimbolo();
            mostraDettaglioStock(s);
        });
        return card;
    }

    // ── Costruttori righe tabella ──────────────────────────────────────────────

    private HBox creaRigaIntestazione(String... colonne) {
        HBox row = new HBox(8);
        row.setStyle("-fx-padding:4 0 4 0; -fx-border-color:transparent transparent #cccccc transparent;");
        for (String col : colonne) {
            Label lbl = new Label(col);
            lbl.setStyle("-fx-font-weight:bold; -fx-font-size:11px; " + CSS_TESTO_GRIGIO);
            lbl.setPrefWidth(120);
            row.getChildren().add(lbl);
        }
        return row;
    }

    private HBox creaRigaPosizione(WalletPositionBean p) {
        HBox row = new HBox(8);
        row.setStyle("-fx-padding:6 0 6 0; -fx-border-color:transparent transparent #eeeeee transparent;");

        double pl = p.getProfittoPerdita();
        String plStr = (pl >= 0 ? "+" : "") + VALUTA.format(pl);
        String plColor = pl >= 0 ? "#2e7d32" : "#d32f2f";

        aggiungiCella(row, p.getStock().getSimbolo(), "-fx-font-weight:bold;");
        aggiungiCella(row, tronca(p.getStock().getNomeAzienda(), 20), CSS_TESTO_GRIGIO);
        aggiungiCella(row, String.format("%.4f", p.getQuantita()), "");
        aggiungiCella(row, String.format(FORMATO_PREZZO, p.getPrezzoMedioAcquisto()), "");
        aggiungiCella(row, VALUTA.format(p.getValoreAttuale()), "");
        aggiungiCella(row, plStr, "-fx-font-weight:bold; -fx-text-fill:" + plColor + ";");
        return row;
    }

    private HBox creaRigaTransazione(TransactionBean t) {
        HBox row = new HBox(8);
        row.setStyle("-fx-padding:6 0 6 0; -fx-border-color:transparent transparent #eeeeee transparent;");

        String data = (t.getQuando() != null)
                ? t.getQuando().format(DateTimeFormatter.ofPattern("dd/MM/yy HH:mm")) : "—";
        aggiungiCella(row, data, CSS_TESTO_GRIGIO);
        aggiungiCella(row, t.getStock() != null ? t.getStock().getSimbolo() : "?",
                "-fx-font-weight:bold;");
        aggiungiCella(row, t.getTipo() != null ? t.getTipo().name() : "?", "");
        aggiungiCella(row, String.format("%.4f", t.getQuantita()), "");
        aggiungiCella(row, VALUTA.format(t.getImportoTotale()), "");
        aggiungiCella(row, t.getStato() != null ? t.getStato().name() : "?",
                CSS_TESTO_GRIGIO);
        return row;
    }

    private void aggiungiCella(HBox row, String testo, String stile) {
        Label lbl = new Label(testo);
        lbl.setPrefWidth(120);
        if (!stile.isEmpty()) lbl.setStyle(stile);
        row.getChildren().add(lbl);
    }

    // ── mostraDettaglioStock() ────────────────────────────────────────────────

    @Override
    protected void mostraDettaglioStock(StockBean s) {
        nascondiPortafoglio();
        nascondiStorico();
        simboloCorrente = s.getSimbolo();
        lblDetSimbolo.setText(s.getSimbolo());
        lblDetNome.setText(s.getNomeAzienda());
        lblDetSettore.setText(s.getSettore());
        lblDetPrezzo.setText(String.format("$ %.4f", s.getPrezzoAttuale()));
        lblDetVariazione.setText(String.format(FORMATO_VARIAZIONE, s.getVariazioneGiornaliera()));

        lblDetVariazione.getStyleClass().removeAll(TAG_POSITIVO, TAG_NEGATIVO);
        lblDetVariazione.getStyleClass().add(
                s.getVariazioneGiornaliera() >= 0 ? TAG_POSITIVO : TAG_NEGATIVO);

        lblDetVarSettimanale.setText(String.format(FORMATO_VARIAZIONE, s.getVariazioneSettimanale()));
        lblDetMarketCap.setText(formatMarketCap(s.getMarketCap()));
        lblDetVolume.setText(s.getVolumeSettimanale() > 0
                ? String.format("%.0f", s.getVolumeSettimanale()) : "—");
        lblDetAggiornamento.setText("Aggiornato: " + LocalDateTime.now(ZoneId.systemDefault()).format(FMT));

        if (isStudente) {
            boxAzioneAcquisto.setVisible(true);  boxAzioneAcquisto.setManaged(true);
            boxSolaLettura.setVisible(false);    boxSolaLettura.setManaged(false);
            PortafoglioBean pf = navigator.getPortafoglio();
            if (pf != null) {
                lblSaldoCheck.setText("Saldo disponibile: " + VALUTA.format(pf.getSaldoDisponibile()));
                boolean saldoOk = pf.getSaldoDisponibile() >= s.getPrezzoAttuale();
                btnCompra.setDisable(!saldoOk);
                btnCompra.setText(saldoOk ? "  Compra ora" : "  Saldo insufficiente");
            }
        } else {
            boxAzioneAcquisto.setVisible(false); boxAzioneAcquisto.setManaged(false);
            boxSolaLettura.setVisible(true);     boxSolaLettura.setManaged(true);
        }

        Stock stockModel = StockService.getInstance().trovaStock(s.getSimbolo());
        if (stockModel != null){
            stockModel.aggiungiObserver(this);
            subjectMap.put(s.getSimbolo(), stockModel);
        }

        panelDettaglio.setVisible(true);
        panelDettaglio.setManaged(true);
        aggiornaGriglia(navigator.getListaStock());
    }

    // ── Handler FXML — Mercato ────────────────────────────────────────────────

    @FXML private void clickCerca()          { nascondiMessaggio(); eseguiRicerca(txtRicerca.getText()); }
    @FXML private void clickAggiorna()       { aggiornaGriglia(navigator.getListaStock()); nascondiMessaggio(); }
    @FXML private void clickQuickSearch(javafx.event.ActionEvent e) {
        String sym = ((Button) e.getSource()).getText();
        txtRicerca.setText(sym);
        eseguiRicerca(sym);
    }
    @FXML private void clickCompra()         { if (simboloCorrente != null) eseguiAvviaOrdine(simboloCorrente); }
    @FXML private void clickDashboard()      { tornaDashboard(); }
    @FXML private void clickLogout()         { StockService.getInstance().fermaAggiornamentoAutomatico(); eseguiLogout(); }

    // ── Handler FXML — Sidebar wallet (studente) ──────────────────────────────

    @FXML private void clickNavPortafoglio() { navigator.goToPortafoglio(); }
    @FXML private void clickNavStorico()     { navigator.goToStorico(); }

    // ── Handler FXML — Conferma ordine ───────────────────────────────────────

    @FXML private void clickConfermaOrdine() {
        try {
            double q = Double.parseDouble(txtQuantita.getText().trim().replace(",", "."));
            if (q <= 0) { mostraErrore("La quantità deve essere maggiore di zero."); return; }
            eseguiConfermaAcquisto(q);
        } catch (NumberFormatException e) {
            mostraErrore("Quantità non valida. Inserisci un numero (es. 2.5).");
        }
    }
    @FXML private void clickAnnullaOrdine()  { eseguiAnnullaOrdine(); }

    // ── Handler FXML — Portafoglio ────────────────────────────────────────────

    @FXML private void clickPortafoglioStorico() { navigator.goToStorico(); }
    @FXML private void clickPortafoglioMercato() {
        if (portafoglioEsterno) tornaDashboard();
        else navigator.goToMercato();
    }

    // ── Handler FXML — Storico ────────────────────────────────────────────────

    @FXML private void clickStoricoPortafoglio() { navigator.goToPortafoglio(); }
    @FXML private void clickStoricoMercato()     { navigator.goToMercato(); }

    // ── Feedback ──────────────────────────────────────────────────────────────

    @Override
    protected void mostraCaricamento(boolean visible) {
        Platform.runLater(() -> { boxCaricamento.setVisible(visible); boxCaricamento.setManaged(visible); });
    }

    @Override
    protected void mostraErrore(String msg) {
        lblMessaggio.setText(msg);
        lblMessaggio.getStyleClass().removeAll("label-successo");
        lblMessaggio.getStyleClass().add("label-errore");
        lblMessaggio.setVisible(true);
        lblMessaggio.setManaged(true);
    }

    @Override
    protected void showMessage(String msg) {
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle("Info"); alert.setHeaderText(null); alert.setContentText(msg);
        alert.showAndWait();
    }

    @Override
    protected void mostraAcquistoCompletato(TransactionBean t) {
        nascondiConfermaOrdine();
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle("Acquisto completato");
        alert.setHeaderText("✅ Ordine eseguito con successo");
        alert.setContentText(String.format(
                "Stock: %s%nQuantità: %.4f azioni%nPrezzo unitario: " + FORMATO_PREZZO + "%nTotale: %s",
                t.getStock().getSimbolo(), t.getQuantita(),
                t.getPrezzoAlMomento(), VALUTA.format(t.getImportoTotale())));
        alert.showAndWait();
        navigator.goToMercato();
    }

    // ── Show / Hide pannelli ──────────────────────────────────────────────────

    private void nascondiTuttiIPannelli() {
        nascondiDettaglio();
        nascondiConfermaOrdine();
        nascondiPortafoglio();
        nascondiStorico();
    }

    private void nascondiDettaglio() {
        if (panelDettaglio != null) { panelDettaglio.setVisible(false); panelDettaglio.setManaged(false); }
    }
    private void nascondiConfermaOrdine() {
        if (panelConfermaOrdine != null) { panelConfermaOrdine.setVisible(false); panelConfermaOrdine.setManaged(false); }
    }
    private void nascondiPortafoglio() {
        if (panelPortafoglio != null) { panelPortafoglio.setVisible(false); panelPortafoglio.setManaged(false); }
    }
    private void nascondiStorico() {
        if (panelStorico != null) { panelStorico.setVisible(false); panelStorico.setManaged(false); }
    }
    private void nascondiMessaggio() {
        lblMessaggio.setText(""); lblMessaggio.setVisible(false); lblMessaggio.setManaged(false);
    }

    // ── Utility ───────────────────────────────────────────────────────────────

    private String tronca(String s, int max) {
        if (s == null) return "—";
        return s.length() <= max ? s : s.substring(0, max - 1) + "…";
    }

    private String formatMarketCap(double cap) {
        if (cap <= 0) return "—";
        if (cap >= 1_000_000_000_000.0) return String.format("$ %.2f T", cap / 1_000_000_000_000.0);
        if (cap >= 1_000_000_000.0)     return String.format("$ %.2f B", cap / 1_000_000_000.0);
        if (cap >= 1_000_000.0)         return String.format("$ %.2f M", cap / 1_000_000.0);
        return VALUTA.format(cap);
    }
}

package org.project.view;

import javafx.application.Platform;
import javafx.fxml.FXML;
import javafx.geometry.Pos;
import javafx.scene.Parent;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import org.project.ing.observer.StockObserver;
import org.project.ing.service.StockService;
import org.project.model.Stock;
import org.project.view.bean.*;

import java.text.NumberFormat;
import java.time.LocalDateTime;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.*;

/**
 * Implementazione GUI (JavaFX) di ManageWalletsGraphicController.
 * Gestisce via panel show/hide tutti i sotto-flussi del caso d'uso:
 * – Mercato (panelDettaglio + griglia stock)
 * – Conferma ordine (panelConfermaOrdine)
 * – Portafoglio proprio / esterno (panelPortafoglio)
 * – Storico transazioni (panelStorico)
 * Tutti i pannelli centrali partono hidden/unmanaged e vengono attivati
 * dal controller nei metodi start*().
 * FXML: ManageWallets.fxml (fx:controller = org.project.view.ManageWalletsGraphicControllerGUI)
 */
public class ManageWalletsGraphicControllerGUI
        extends ManageWalletsGraphicController
        implements StockObserver {

    private static final String LABEL_TOTALE_VUOTO = "Totale: —";
    private static final String CSS_TESTO_SECONDARIO = "testo-secondario";
    private static final String CSS_TESTO_GRIGIO = "-fx-text-fill:#555555;";
    private static final String FORMATO_PREZZO = "$ %.2f";
    private static final String FORMATO_VARIAZIONE = "%+.2f%%";
    private static final String TAG_POSITIVO = "tag-positivo";
    private static final String TAG_NEGATIVO = "tag-negativo";

    // ── FXML Sidebar ──────────────────────────────────────────────────────────
    @FXML private Label            lblRuoloSidebar;
    @FXML private VBox             boxInfoUtente;
    @FXML private Label            lblNomeUtente;
    @FXML private Label            lblSaldoSidebar;
    @FXML private VBox             boxNavWallet;

    // ── FXML Header ───────────────────────────────────────────────────────────
    @FXML private Label            lblSottotitoloMercato;
    @FXML private TextField        txtRicerca;

    // ── FXML Feedback ─────────────────────────────────────────────────────────
    @FXML private Label            lblMessaggio;
    @FXML private HBox             boxCaricamento;

    // ── FXML Pannello dettaglio stock ─────────────────────────────────────────
    @FXML private VBox             panelDettaglio;
    @FXML private Label            lblDetSimbolo;
    @FXML private Label            lblDetNome;
    @FXML private Label            lblDetSettore;
    @FXML private Label            lblDetPrezzo;
    @FXML private Label            lblDetVariazione;
    @FXML private Label            lblDetVarSettimanale;
    @FXML private Label            lblDetMarketCap;
    @FXML private Label            lblDetVolume;
    @FXML private Label            lblDetAggiornamento;
    @FXML private VBox             boxAzioneAcquisto;
    @FXML private Label            lblSaldoCheck;
    @FXML private Button           btnCompra;
    @FXML private VBox             boxSolaLettura;

    // ── FXML Pannello conferma ordine ─────────────────────────────────────────
    @FXML private VBox             panelConfermaOrdine;
    @FXML private Label            lblOrdineStock;
    @FXML private Label            lblOrdinePrezzo;
    @FXML private Label            lblOrdineSaldo;
    @FXML private TextField        txtQuantita;
    @FXML private Label            lblOrdineTotale;
    @FXML private Button           btnConfermaOrdine;

    // ── FXML Pannello portafoglio ─────────────────────────────────────────────
    @FXML private VBox             panelPortafoglio;
    @FXML private Label            lblTitoloPortafoglio;
    @FXML private Label            lblSaldoPortafoglio;
    @FXML private Label            lblTotalePortafoglio;
    @FXML private VBox             vboxPosizioni;
    @FXML private Button           btnPortafoglioStorico;
    @FXML private Button           btnPortafoglioTorna;

    // ── FXML Pannello storico transazioni ─────────────────────────────────────
    @FXML private VBox             panelStorico;
    @FXML private Label            lblTitoloStorico;
    @FXML private VBox             vboxStorico;

    // ── FXML Griglia mercato ──────────────────────────────────────────────────
    @FXML private FlowPane         flowStocks;
    @FXML private Label            lblTitoloGriglia;
    @FXML private Label            lblContatore;
    @FXML private Label            lblNessunoStock;

    private Parent  view;
    private String  simboloCorrente;
    private boolean portafoglioEsterno = false;

    private final Map<String, Label> prezziInGriglia = new HashMap<>();
    private final Map<String, Stock> subjectMap = new HashMap<>();

    private static final NumberFormat  VALUTA = NumberFormat.getCurrencyInstance(Locale.ITALY);
    private static final DateTimeFormatter FMT = DateTimeFormatter.ofPattern("dd/MM/yyyy HH:mm:ss");

    // ── Setter / Getter ───────────────────────────────────────────────────────

    public void setView(Parent view)              { this.view = view; }
    public Parent getView()                       { return view; }
    public void setGuiNavigator(NavigatorGUI nav) { super.setNavigator(nav); }

    // ── start() — schermata mercato ───────────────────────────────────────────

    @Override
    public void start() {
        nascondiTuttiIPannelli();
        nascondiMessaggio();
        portafoglioEsterno = false;

        SessioneBean sessione = navigator.getSessione();
        if (isStudente) {
            String nome = (sessione != null && sessione.getStudente() != null)
                    ? sessione.getStudente().getNome() : "—";
            lblNomeUtente.setText(nome);
            lblRuoloSidebar.setText("Manage Wallets · Studente");
            boxInfoUtente.getStyleClass().removeAll("card-professore");
            boxInfoUtente.getStyleClass().add("card-studente");
            lblSottotitoloMercato.setText("Esplora il mercato e investi nei tuoi titoli preferiti");

            PortafoglioBean pf = navigator.getPortafoglio();
            lblSaldoSidebar.setText(pf != null
                    ? "Saldo: " + VALUTA.format(pf.getSaldoDisponibile()) : "");

            if (boxNavWallet != null) {
                boxNavWallet.setVisible(true);
                boxNavWallet.setManaged(true);
            }
        } else {
            String nome = (sessione != null && sessione.getProfessore() != null)
                    ? "Prof. " + sessione.getProfessore().getNome() : "—";
            lblNomeUtente.setText(nome);
            lblRuoloSidebar.setText("Manage Wallets · Professore");
            boxInfoUtente.getStyleClass().removeAll("card-studente");
            boxInfoUtente.getStyleClass().add("card-professore");
            lblSaldoSidebar.setText("Visualizzazione in sola lettura");
            lblSottotitoloMercato.setText("Monitora gli andamenti del mercato");

            if (boxNavWallet != null) {
                boxNavWallet.setVisible(false);
                boxNavWallet.setManaged(false);
            }
        }

        aggiornaGriglia(navigator.getListaStock());
        StockService.getInstance().avviaAggiornamentoAutomatico();
    }

    // ── startConfermaOrdine() ─────────────────────────────────────────────────

    @Override
    public void startConfermaOrdine() {
        TransactionBean t = navigator.getTransazionePending();
        if (t == null) {
            mostraErrore("Nessun ordine da confermare.");
            return;
        }

        nascondiTuttiIPannelli();
        nascondiMessaggio();

        lblOrdineStock.setText(t.getStock().getSimbolo() + " — " + t.getStock().getNomeAzienda());
        lblOrdinePrezzo.setText(String.format("Prezzo unitario: " + FORMATO_PREZZO, t.getPrezzoAlMomento()));

        PortafoglioBean pf = navigator.getPortafoglio();
        lblOrdineSaldo.setText(pf != null
                ? "Saldo disponibile: " + VALUTA.format(pf.getSaldoDisponibile()) : "");

        resettaCampiOrdine();

        txtQuantita.textProperty().addListener((obs, oldV, newV) ->
                aggiornaTotaleOrdine(newV, t, pf)
        );

        panelConfermaOrdine.setVisible(true);
        panelConfermaOrdine.setManaged(true);
    }

    private void resettaCampiOrdine() {
        txtQuantita.clear();
        lblOrdineTotale.setText(LABEL_TOTALE_VUOTO);
        if (btnConfermaOrdine != null) btnConfermaOrdine.setDisable(true);
    }

    private void aggiornaTotaleOrdine(String quantitaInserita, TransactionBean t, PortafoglioBean pf) {
        try {
            double q = Double.parseDouble(quantitaInserita.replace(",", "."));
            if (q > 0) {
                double totale = q * t.getPrezzoAlMomento();
                lblOrdineTotale.setText("Totale: " + VALUTA.format(totale));
                boolean saldoOk = pf == null || pf.getSaldoDisponibile() >= totale;

                if (btnConfermaOrdine != null) btnConfermaOrdine.setDisable(!saldoOk);

                lblOrdineTotale.setStyle(saldoOk
                        ? "-fx-text-fill:#2e7d32; -fx-font-weight:bold;"
                        : "-fx-text-fill:#d32f2f; -fx-font-weight:bold;");
            } else {
                resettaCampiOrdine();
            }
        } catch (NumberFormatException e) {
            resettaCampiOrdine();
        }
    }

    // ── startPortafoglio() ────────────────────────────────────────────────────

    @Override
    public void startPortafoglio() {
        nascondiTuttiIPannelli();
        nascondiMessaggio();
        portafoglioEsterno = false;
        // Portafoglio proprio: non richiedere uno studente target (emailTarget = null)
        eseguiCaricaPortafoglio(null);
    }

    // ── startStorico() ────────────────────────────────────────────────────────

    @Override
    public void startStorico() {
        nascondiTuttiIPannelli();
        nascondiMessaggio();
        // Storico proprio: non richiedere uno studente target (emailTarget = null)
        eseguiCaricaStorico(null);
    }

    // ── startWalletEsterno() ──────────────────────────────────────────────────

    @Override
    public void startWalletEsterno(StudenteBean studenteTarget) {
        nascondiTuttiIPannelli();
        nascondiMessaggio();
        portafoglioEsterno = true;
        eseguiCaricaPortafoglio(studenteTarget.getEmail());
    }

    // ── mostraPortafoglio() ───────────────────────────────────────────────────

    @Override
    protected void mostraPortafoglio(PortafoglioBean pf, boolean isProprietario) {
        Platform.runLater(() -> {
            impostaTitoloPortafoglio(isProprietario);

            if (pf == null) {
                mostraPortafoglioVuoto();
            } else {
                popolaDatiPortafoglio(pf);
            }

            impostaPulsantiNavigazionePortafoglio(isProprietario);

            panelPortafoglio.setVisible(true);
            panelPortafoglio.setManaged(true);
        });
    }

    private void impostaTitoloPortafoglio(boolean isProprietario) {
        lblTitoloPortafoglio.setText(isProprietario
                ? " Il Tuo Portafoglio"
                : " Portafoglio (sola lettura)");
    }

    private void mostraPortafoglioVuoto() {
        lblSaldoPortafoglio.setText("Nessun dato disponibile.");
        lblTotalePortafoglio.setText("");
        vboxPosizioni.getChildren().clear();
    }

    private void popolaDatiPortafoglio(PortafoglioBean pf) {
        lblSaldoPortafoglio.setText(" Saldo disponibile: " + VALUTA.format(pf.getSaldoDisponibile()));
        lblTotalePortafoglio.setText(" Valore totale wallet: " + VALUTA.format(pf.getValoreTotalePortafoglio()));

        vboxPosizioni.getChildren().clear();

        if (pf.getPosizioni() == null || pf.getPosizioni().isEmpty()) {
            Label nessuna = new Label("Nessuna posizione aperta.");
            nessuna.getStyleClass().add(CSS_TESTO_SECONDARIO);
            vboxPosizioni.getChildren().add(nessuna);
        } else {
            HBox header = creaRigaIntestazione("Simbolo", "Azienda", "Quantità", "Pr.Medio", "Val.Att.", "P/L");
            vboxPosizioni.getChildren().add(header);

            for (WalletPositionBean p : pf.getPosizioni()) {
                vboxPosizioni.getChildren().add(creaRigaPosizione(p));
            }
        }
    }

    private void impostaPulsantiNavigazionePortafoglio(boolean isProprietario) {
        if (btnPortafoglioStorico != null) {
            btnPortafoglioStorico.setVisible(isProprietario);
            btnPortafoglioStorico.setManaged(isProprietario);
        }

        if (btnPortafoglioTorna != null) {
            btnPortafoglioTorna.setVisible(isProprietario);
            btnPortafoglioTorna.setManaged(isProprietario);
        }
    }

    // ── mostraStorico() ───────────────────────────────────────────────────────

    @Override
    protected void mostraStorico(List<TransactionBean> storico, String emailTarget) {
        Platform.runLater(() -> {
            lblTitoloStorico.setText(emailTarget == null
                    ? " Storico Transazioni"
                    : " Storico Transazioni (sola lettura)");

            vboxStorico.getChildren().clear();

            if (storico == null || storico.isEmpty()) {
                Label nessuna = new Label("Nessuna transazione registrata.");
                nessuna.getStyleClass().add(CSS_TESTO_SECONDARIO);
                vboxStorico.getChildren().add(nessuna);
            } else {
                HBox header = creaRigaIntestazione("Data", "Simbolo", "Tipo", "Quantità", "Importo", "Stato");
                vboxStorico.getChildren().add(header);
                for (TransactionBean t : storico) {
                    vboxStorico.getChildren().add(creaRigaTransazione(t));
                }
            }

            panelStorico.setVisible(true);
            panelStorico.setManaged(true);
        });
    }

    // ── StockObserver ─────────────────────────────────────────────────────────

    @Override
    public void aggiornamento() {
        Platform.runLater(() -> {

            for (Map.Entry<String, Stock> entry : subjectMap.entrySet()) {
                double nuovoPrezzo = entry.getValue().getState(); // getState() GoF
                Label lbl = prezziInGriglia.get(entry.getKey());
                if (lbl != null)
                    lbl.setText(String.format(FORMATO_PREZZO, nuovoPrezzo));
            }

            // Aggiorna il pannello dettaglio se è aperto
            if (simboloCorrente != null) {
                Stock s = subjectMap.get(simboloCorrente);
                if (s != null) {
                    lblDetPrezzo.setText(String.format(FORMATO_PREZZO, s.getState()));
                    lblDetVariazione.setText(String.format(FORMATO_VARIAZIONE,
                            s.variazioneGiornaliera()));
                    lblDetAggiornamento.setText("Aggiornato: "
                            + LocalDateTime.now(ZoneId.systemDefault()).format(FMT));

                    lblDetVariazione.getStyleClass().removeAll(TAG_POSITIVO, TAG_NEGATIVO);
                    lblDetVariazione.getStyleClass().add(
                            s.variazioneGiornaliera() >= 0 ? TAG_POSITIVO : TAG_NEGATIVO);
                }
            }
        });
    }

    // ── Griglia stock ─────────────────────────────────────────────────────────

    private void aggiornaGriglia(List<StockBean> lista) {
        flowStocks.getChildren().clear();
        prezziInGriglia.clear();

        if (lista == null || lista.isEmpty()) {
            lblNessunoStock.setVisible(true);
            lblNessunoStock.setManaged(true);
            lblContatore.setText("");
            return;
        }

        lblNessunoStock.setVisible(false);
        lblNessunoStock.setManaged(false);
        lblContatore.setText("(" + lista.size() + " titoli)");

        for (StockBean s : lista) {
            flowStocks.getChildren().add(creaCardStock(s));
            Stock sm = StockService.getInstance().trovaStock(s.getSimbolo());
            if (sm != null) {
                sm.aggiungiObserver(this);
                subjectMap.put(s.getSimbolo(), sm);
            }
        }
    }

    private VBox creaCardStock(StockBean s) {
        VBox card = new VBox(10);
        card.setPrefWidth(260);
        card.getStyleClass().add("card-stock");
        card.setStyle(card.getStyle() + "; -fx-cursor:hand;");

        HBox top = new HBox(8);
        top.setAlignment(Pos.CENTER_LEFT);
        Label lblSim = new Label(s.getSimbolo());
        lblSim.getStyleClass().add("simbolo-stock");

        double variazione = s.getVariazioneGiornaliera();
        Label lblVar = new Label(String.format(FORMATO_VARIAZIONE, variazione));
        lblVar.getStyleClass().add(variazione >= 0 ? TAG_POSITIVO : TAG_NEGATIVO);

        HBox spacer = new HBox(); HBox.setHgrow(spacer, Priority.ALWAYS);
        top.getChildren().addAll(lblSim, spacer, lblVar);

        Label lblNome   = new Label(tronca(s.getNomeAzienda(), 28));
        lblNome.getStyleClass().add(CSS_TESTO_SECONDARIO);
        Label lblPrezzo = new Label(String.format(FORMATO_PREZZO, s.getPrezzoAttuale()));
        lblPrezzo.setStyle("-fx-font-size:20px; -fx-font-weight:bold; -fx-text-fill:#1a1a2e;");
        prezziInGriglia.put(s.getSimbolo(), lblPrezzo);
        Label lblSett = new Label(s.getSettore());
        lblSett.getStyleClass().add(CSS_TESTO_SECONDARIO);
        lblSett.setStyle(lblSett.getStyle() + "; -fx-font-size:10px;");
        card.getChildren().addAll(top, lblNome, lblPrezzo, lblSett);

        card.setOnMouseClicked(e -> {
            nascondiConfermaOrdine();
            nascondiPortafoglio();
            nascondiStorico();
            simboloCorrente = s.getSimbolo();
            mostraDettaglioStock(s);
        });
        return card;
    }

    // ── Costruttori righe tabella ──────────────────────────────────────────────

    private HBox creaRigaIntestazione(String... colonne) {
        HBox row = new HBox(8);
        row.setStyle("-fx-padding:4 0 4 0; -fx-border-color:transparent transparent #cccccc transparent;");
        for (String col : colonne) {
            Label lbl = new Label(col);
            lbl.setStyle("-fx-font-weight:bold; -fx-font-size:11px; " + CSS_TESTO_GRIGIO);
            lbl.setPrefWidth(120);
            row.getChildren().add(lbl);
        }
        return row;
    }

    private HBox creaRigaPosizione(WalletPositionBean p) {
        HBox row = new HBox(8);
        row.setStyle("-fx-padding:6 0 6 0; -fx-border-color:transparent transparent #eeeeee transparent;");

        double pl = p.getProfittoPerdita();
        String plStr = (pl >= 0 ? "+" : "") + VALUTA.format(pl);
        String plColor = pl >= 0 ? "#2e7d32" : "#d32f2f";

        aggiungiCella(row, p.getStock().getSimbolo(), "-fx-font-weight:bold;");
        aggiungiCella(row, tronca(p.getStock().getNomeAzienda(), 20), CSS_TESTO_GRIGIO);
        aggiungiCella(row, String.format("%.4f", p.getQuantita()), "");
        aggiungiCella(row, String.format(FORMATO_PREZZO, p.getPrezzoMedioAcquisto()), "");
        aggiungiCella(row, VALUTA.format(p.getValoreAttuale()), "");
        aggiungiCella(row, plStr, "-fx-font-weight:bold; -fx-text-fill:" + plColor + ";");
        return row;
    }

    private HBox creaRigaTransazione(TransactionBean t) {
        HBox row = new HBox(8);
        row.setStyle("-fx-padding:6 0 6 0; -fx-border-color:transparent transparent #eeeeee transparent;");

        String data = (t.getQuando() != null)
                ? t.getQuando().format(DateTimeFormatter.ofPattern("dd/MM/yy HH:mm")) : "—";
        aggiungiCella(row, data, CSS_TESTO_GRIGIO);
        aggiungiCella(row, t.getStock() != null ? t.getStock().getSimbolo() : "?",
                "-fx-font-weight:bold;");
        aggiungiCella(row, t.getTipo() != null ? t.getTipo().name() : "?", "");
        aggiungiCella(row, String.format("%.4f", t.getQuantita()), "");
        aggiungiCella(row, VALUTA.format(t.getImportoTotale()), "");
        aggiungiCella(row, t.getStato() != null ? t.getStato().name() : "?",
                CSS_TESTO_GRIGIO);
        return row;
    }

    private void aggiungiCella(HBox row, String testo, String stile) {
        Label lbl = new Label(testo);
        lbl.setPrefWidth(120);
        if (!stile.isEmpty()) lbl.setStyle(stile);
        row.getChildren().add(lbl);
    }

    // ── mostraDettaglioStock() ────────────────────────────────────────────────

    @Override
    protected void mostraDettaglioStock(StockBean s) {
        nascondiPortafoglio();
        nascondiStorico();
        simboloCorrente = s.getSimbolo();
        lblDetSimbolo.setText(s.getSimbolo());
        lblDetNome.setText(s.getNomeAzienda());
        lblDetSettore.setText(s.getSettore());
        lblDetPrezzo.setText(String.format("$ %.4f", s.getPrezzoAttuale()));
        lblDetVariazione.setText(String.format(FORMATO_VARIAZIONE, s.getVariazioneGiornaliera()));

        lblDetVariazione.getStyleClass().removeAll(TAG_POSITIVO, TAG_NEGATIVO);
        lblDetVariazione.getStyleClass().add(
                s.getVariazioneGiornaliera() >= 0 ? TAG_POSITIVO : TAG_NEGATIVO);

        lblDetVarSettimanale.setText(String.format(FORMATO_VARIAZIONE, s.getVariazioneSettimanale()));
        lblDetMarketCap.setText(formatMarketCap(s.getMarketCap()));
        lblDetVolume.setText(s.getVolumeSettimanale() > 0
                ? String.format("%.0f", s.getVolumeSettimanale()) : "—");
        lblDetAggiornamento.setText("Aggiornato: " + LocalDateTime.now(ZoneId.systemDefault()).format(FMT));

        if (isStudente) {
            boxAzioneAcquisto.setVisible(true);  boxAzioneAcquisto.setManaged(true);
            boxSolaLettura.setVisible(false);    boxSolaLettura.setManaged(false);
            PortafoglioBean pf = navigator.getPortafoglio();
            if (pf != null) {
                lblSaldoCheck.setText("Saldo disponibile: " + VALUTA.format(pf.getSaldoDisponibile()));
                boolean saldoOk = pf.getSaldoDisponibile() >= s.getPrezzoAttuale();
                btnCompra.setDisable(!saldoOk);
                btnCompra.setText(saldoOk ? "  Compra ora" : "  Saldo insufficiente");
            }
        } else {
            boxAzioneAcquisto.setVisible(false); boxAzioneAcquisto.setManaged(false);
            boxSolaLettura.setVisible(true);     boxSolaLettura.setManaged(true);
        }

        Stock stockModel = StockService.getInstance().trovaStock(s.getSimbolo());
        if (stockModel != null){
            stockModel.aggiungiObserver(this);
            subjectMap.put(s.getSimbolo(), stockModel);
        }

        panelDettaglio.setVisible(true);
        panelDettaglio.setManaged(true);
        aggiornaGriglia(navigator.getListaStock());
    }

    // ── Handler FXML — Mercato ────────────────────────────────────────────────

    @FXML private void clickCerca()          { nascondiMessaggio(); eseguiRicerca(txtRicerca.getText()); }
    @FXML private void clickAggiorna()       { aggiornaGriglia(navigator.getListaStock()); nascondiMessaggio(); }
    @FXML private void clickQuickSearch(javafx.event.ActionEvent e) {
        String sym = ((Button) e.getSource()).getText();
        txtRicerca.setText(sym);
        eseguiRicerca(sym);
    }
    @FXML private void clickCompra()         { if (simboloCorrente != null) eseguiAvviaOrdine(simboloCorrente); }
    @FXML private void clickDashboard()      { tornaDashboard(); }
    @FXML private void clickLogout()         { StockService.getInstance().fermaAggiornamentoAutomatico(); eseguiLogout(); }

    // ── Handler FXML — Sidebar wallet (studente) ──────────────────────────────

    @FXML private void clickNavPortafoglio() { navigator.goToPortafoglio(); }
    @FXML private void clickNavStorico()     { navigator.goToStorico(); }

    // ── Handler FXML — Conferma ordine ───────────────────────────────────────

    @FXML private void clickConfermaOrdine() {
        try {
            double q = Double.parseDouble(txtQuantita.getText().trim().replace(",", "."));
            if (q <= 0) { mostraErrore("La quantità deve essere maggiore di zero."); return; }
            eseguiConfermaAcquisto(q);
        } catch (NumberFormatException e) {
            mostraErrore("Quantità non valida. Inserisci un numero (es. 2.5).");
        }
    }
    @FXML private void clickAnnullaOrdine()  { eseguiAnnullaOrdine(); }

    // ── Handler FXML — Portafoglio ────────────────────────────────────────────

    @FXML private void clickPortafoglioStorico() { navigator.goToStorico(); }
    @FXML private void clickPortafoglioMercato() {
        if (portafoglioEsterno) tornaDashboard();
        else navigator.goToMercato();
    }

    // ── Handler FXML — Storico ────────────────────────────────────────────────

    @FXML private void clickStoricoPortafoglio() { navigator.goToPortafoglio(); }
    @FXML private void clickStoricoMercato()     { navigator.goToMercato(); }

    // ── Feedback ──────────────────────────────────────────────────────────────

    @Override
    protected void mostraCaricamento(boolean visible) {
        Platform.runLater(() -> { boxCaricamento.setVisible(visible); boxCaricamento.setManaged(visible); });
    }

    @Override
    protected void mostraErrore(String msg) {
        lblMessaggio.setText(msg);
        lblMessaggio.getStyleClass().removeAll("label-successo");
        lblMessaggio.getStyleClass().add("label-errore");
        lblMessaggio.setVisible(true);
        lblMessaggio.setManaged(true);
    }

    @Override
    protected void showMessage(String msg) {
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle("Info"); alert.setHeaderText(null); alert.setContentText(msg);
        alert.showAndWait();
    }

    @Override
    protected void mostraAcquistoCompletato(TransactionBean t) {
        nascondiConfermaOrdine();
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle("Acquisto completato");
        alert.setHeaderText("✅ Ordine eseguito con successo");
        alert.setContentText(String.format(
                "Stock: %s%nQuantità: %.4f azioni%nPrezzo unitario: " + FORMATO_PREZZO + "%nTotale: %s",
                t.getStock().getSimbolo(), t.getQuantita(),
                t.getPrezzoAlMomento(), VALUTA.format(t.getImportoTotale())));
        alert.showAndWait();
        navigator.goToMercato();
    }

    // ── Show / Hide pannelli ──────────────────────────────────────────────────

    private void nascondiTuttiIPannelli() {
        nascondiDettaglio();
        nascondiConfermaOrdine();
        nascondiPortafoglio();
        nascondiStorico();
    }

    private void nascondiDettaglio() {
        if (panelDettaglio != null) { panelDettaglio.setVisible(false); panelDettaglio.setManaged(false); }
    }
    private void nascondiConfermaOrdine() {
        if (panelConfermaOrdine != null) { panelConfermaOrdine.setVisible(false); panelConfermaOrdine.setManaged(false); }
    }
    private void nascondiPortafoglio() {
        if (panelPortafoglio != null) { panelPortafoglio.setVisible(false); panelPortafoglio.setManaged(false); }
    }
    private void nascondiStorico() {
        if (panelStorico != null) { panelStorico.setVisible(false); panelStorico.setManaged(false); }
    }
    private void nascondiMessaggio() {
        lblMessaggio.setText(""); lblMessaggio.setVisible(false); lblMessaggio.setManaged(false);
    }

    // ── Utility ───────────────────────────────────────────────────────────────

    private String tronca(String s, int max) {
        if (s == null) return "—";
        return s.length() <= max ? s : s.substring(0, max - 1) + "…";
    }

    private String formatMarketCap(double cap) {
        if (cap <= 0) return "—";
        if (cap >= 1_000_000_000_000.0) return String.format("$ %.2f T", cap / 1_000_000_000_000.0);
        if (cap >= 1_000_000_000.0)     return String.format("$ %.2f B", cap / 1_000_000_000.0);
        if (cap >= 1_000_000.0)         return String.format("$ %.2f M", cap / 1_000_000.0);
        return VALUTA.format(cap);
    }
}

package org.project.view;

import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

import java.io.IOException;
import java.util.Objects;

/**
 * Navigator GUI — gestisce la navigazione JavaFX.
 *
 * ── Strategia di caricamento FXML ────────────────────────────────────────────
 * Approccio A  (caricaFXML):       controller istanziato qui, passato via
 *                                   setController(). L'FXML non dichiara fx:controller.
 * Approccio B  (caricaManageWallets): il controller è dichiarato nell'FXML con
 *                                   fx:controller; lo recuperiamo via getController()
 *                                   dopo il load() e completiamo il wiring.
 *
 * ── Caso d'uso ManageWallets ─────────────────────────────────────────────────
 * Tutte le schermate del caso d'uso (MERCATO, CONFERMA_ORDINE, PORTAFOGLIO,
 * STORICO, WALLET_STUDENTE) condividono la stessa istanza ManageWalletsGraphicControllerGUI
 * e la stessa view (ManageWallets.fxml); ogni chiamata attiva un diverso
 * entry-point (start, startConfermaOrdine, startPortafoglio, ...).
 */
public class NavigatorGUI extends Navigator {

    private final Stage stage;

    private LoginGraphicControllerGUI            login;
    private HomeStudenteGraphicControllerGUI     homeStudente;
    private HomeProfessoreGraphicControllerGUI   homeProfessore;
    private ManageWalletsGraphicControllerGUI    manageWallets;
    private GestioneClasseGraphicControllerGUI   gestioneClasse;

    public NavigatorGUI() {
        super();
        this.stage = new Stage();
        this.stage.setTitle("UniFinance");
        this.stage.setMinWidth(600);
        this.stage.setMinHeight(400);
    }

    @Override
    public void startUp() {
        goToLogin();
    }

    // ── Cambio schermata ──────────────────────────────────────────────────────

    private void mostraSchermata(Parent view) {
        Scene scene = stage.getScene();
        if (scene == null) {
            scene = new Scene(view);
            stage.setScene(scene);
        } else {
            scene.setRoot(view);
        }
        stage.show();
    }

    // ── Approccio A: setController() ─────────────────────────────────────────

    private <T> T caricaFXML(String nomeFile, Object controller) {
        try {
            FXMLLoader loader = new FXMLLoader(
                    Objects.requireNonNull(
                            getClass().getResource("/fxml/" + nomeFile),
                            "FXML non trovato: " + nomeFile));
            loader.setController(controller);
            return loader.load();
        } catch (IOException e) {
            throw new RuntimeException("Impossibile caricare " + nomeFile, e);
        }
    }

    // ── Approccio B: getController() — ManageWallets.fxml ────────────────────

    private ManageWalletsGraphicControllerGUI caricaManageWallets() {
        try {
            FXMLLoader loader = new FXMLLoader(
                    Objects.requireNonNull(
                            getClass().getResource("/fxml/ManageWallets.fxml"),
                            "FXML non trovato: ManageWallets.fxml"));
            Parent view = loader.load();
            ManageWalletsGraphicControllerGUI ctrl = loader.getController();
            ctrl.setGuiNavigator(this);
            ctrl.setView(view);
            return ctrl;
        } catch (IOException e) {
            throw new RuntimeException("Impossibile caricare ManageWallets.fxml", e);
        }
    }

    // ── Schermate ─────────────────────────────────────────────────────────────

    @Override
    protected void visualizzaLogin() {
        if (this.login == null) {
            this.login = new LoginGraphicControllerGUI();
            this.login.setGuiNavigator(this);
            Parent view = caricaFXML("Login.fxml", this.login);
            this.login.setView(view);
        }
        this.login.start();
        mostraSchermata(this.login.getView());
    }

    @Override
    protected void visualizzaRegistrazione() {
        System.out.println("[Registrazione GUI — da implementare]");
    }

    @Override
    protected void visualizzaHomeStudente() {
        if (this.homeStudente == null) {
            this.homeStudente = new HomeStudenteGraphicControllerGUI();
            this.homeStudente.setGuiNavigator(this);
            Parent view = caricaFXML("HomeStudente.fxml", this.homeStudente);
            this.homeStudente.setView(view);
        }
        this.homeStudente.start();
        mostraSchermata(this.homeStudente.getView());
    }

    // ── ManageWallets — tutti gli entry-point riusano la stessa istanza ───────

    private ManageWalletsGraphicControllerGUI getManageWallets() {
        if (this.manageWallets == null)
            this.manageWallets = caricaManageWallets();
        return this.manageWallets;
    }

    @Override
    protected void visualizzaMercato() {
        getManageWallets().start();
        mostraSchermata(this.manageWallets.getView());
    }

    @Override
    protected void visualizzaDettaglioStock() {
        // Gestito inline dal panel dettaglio all'interno di ManageWallets.fxml
    }

    @Override
    protected void visualizzaConfermaOrdine() {
        getManageWallets().startConfermaOrdine();
        mostraSchermata(this.manageWallets.getView());
    }

    @Override
    protected void visualizzaPortafoglio() {
        getManageWallets().startPortafoglio();
        mostraSchermata(this.manageWallets.getView());
    }

    @Override
    protected void visualizzaStorico() {
        getManageWallets().startStorico();
        mostraSchermata(this.manageWallets.getView());
    }

    /**
     * Visualizza il portafoglio di studenteTarget in sola lettura.
     * Richiede impostaStudenteTarget() prima della chiamata.
     */
    @Override
    protected void visualizzaWalletStudente() {
        var target = getStudenteTarget();
        if (target == null) {
            System.err.println("[NavigatorGUI] visualizzaWalletStudente: studenteTarget non impostato");
            return;
        }
        getManageWallets().startWalletEsterno(target);
        mostraSchermata(this.manageWallets.getView());
    }

    // ── Professore ────────────────────────────────────────────────────────────

    @Override
    protected void visualizzaHomeProfessore() {
        if (this.homeProfessore == null) {
            this.homeProfessore = new HomeProfessoreGraphicControllerGUI();
            this.homeProfessore.setGuiNavigator(this);
            Parent view = caricaFXML("HomeProfessore.fxml", this.homeProfessore);
            this.homeProfessore.setView(view);
        }
        this.homeProfessore.start();
        mostraSchermata(this.homeProfessore.getView());
    }

    @Override
    protected void visualizzaGestioneClasse() {
        if (this.gestioneClasse == null) {
            this.gestioneClasse = new GestioneClasseGraphicControllerGUI();
            this.gestioneClasse.setGuiNavigator(this);
            Parent view = caricaFXML("GestioneClasse.fxml", this.gestioneClasse);
            this.gestioneClasse.setView(view);
        }
        this.gestioneClasse.start();
        mostraSchermata(this.gestioneClasse.getView());
    }

    @Override
    protected void visualizzaElencoStudenti() {
        System.out.println("[Elenco Studenti GUI — da implementare]");
    }

    // ── Logout ────────────────────────────────────────────────────────────────

    @Override
    public void logout() {
        // Resetta il controller ManageWallets prima di liberarlo
        if (this.manageWallets != null) {
            this.manageWallets.reset();
        }

        // Libera tutti i controller
        this.login          = null;
        this.homeStudente   = null;
        this.homeProfessore = null;
        this.manageWallets  = null;
        this.gestioneClasse = null;
    }
}

package org.project.view;

import javafx.fxml.FXMLLoader;
import javafx.scene.Parent;
import javafx.scene.Scene;
import javafx.stage.Stage;

import java.io.IOException;
import java.util.Objects;

/**
 * Navigator GUI — gestisce la navigazione JavaFX.
 *
 * ── Strategia di caricamento FXML ────────────────────────────────────────────
 * Approccio A  (caricaFXML):       controller istanziato qui, passato via
 *                                   setController(). L'FXML non dichiara fx:controller.
 * Approccio B  (caricaManageWallets): il controller è dichiarato nell'FXML con
 *                                   fx:controller; lo recuperiamo via getController()
 *                                   dopo il load() e completiamo il wiring.
 *
 * ── Caso d'uso ManageWallets ─────────────────────────────────────────────────
 * Tutte le schermate del caso d'uso (MERCATO, CONFERMA_ORDINE, PORTAFOGLIO,
 * STORICO, WALLET_STUDENTE) condividono la stessa istanza ManageWalletsGraphicControllerGUI
 * e la stessa view (ManageWallets.fxml); ogni chiamata attiva un diverso
 * entry-point (start, startConfermaOrdine, startPortafoglio, ...).
 */
public class NavigatorGUI extends Navigator {

    private final Stage stage;

    private LoginGraphicControllerGUI            login;
    private HomeStudenteGraphicControllerGUI     homeStudente;
    private HomeProfessoreGraphicControllerGUI   homeProfessore;
    private ManageWalletsGraphicControllerGUI    manageWallets;
    private GestioneClasseGraphicControllerGUI   gestioneClasse;

    public NavigatorGUI() {
        super();
        this.stage = new Stage();
        this.stage.setTitle("UniFinance");
        this.stage.setMinWidth(600);
        this.stage.setMinHeight(400);
    }

    @Override
    public void startUp() {
        goToLogin();
    }

    // ── Cambio schermata ──────────────────────────────────────────────────────

    private void mostraSchermata(Parent view) {
        Scene scene = stage.getScene();
        if (scene == null) {
            scene = new Scene(view);
            stage.setScene(scene);
        } else {
            scene.setRoot(view);
        }
        stage.show();
    }

    // ── Approccio A: setController() ─────────────────────────────────────────

    private <T> T caricaFXML(String nomeFile, Object controller) {
        try {
            FXMLLoader loader = new FXMLLoader(
                    Objects.requireNonNull(
                            getClass().getResource("/fxml/" + nomeFile),
                            "FXML non trovato: " + nomeFile));
            loader.setController(controller);
            return loader.load();
        } catch (IOException e) {
            throw new RuntimeException("Impossibile caricare " + nomeFile, e);
        }
    }

    // ── Approccio B: getController() — ManageWallets.fxml ────────────────────

    private ManageWalletsGraphicControllerGUI caricaManageWallets() {
        try {
            FXMLLoader loader = new FXMLLoader(
                    Objects.requireNonNull(
                            getClass().getResource("/fxml/ManageWallets.fxml"),
                            "FXML non trovato: ManageWallets.fxml"));
            Parent view = loader.load();
            ManageWalletsGraphicControllerGUI ctrl = loader.getController();
            ctrl.setGuiNavigator(this);
            ctrl.setView(view);
            return ctrl;
        } catch (IOException e) {
            throw new RuntimeException("Impossibile caricare ManageWallets.fxml", e);
        }
    }

    // ── Schermate ─────────────────────────────────────────────────────────────

    @Override
    protected void visualizzaLogin() {
        if (this.login == null) {
            this.login = new LoginGraphicControllerGUI();
            this.login.setGuiNavigator(this);
            Parent view = caricaFXML("Login.fxml", this.login);
            this.login.setView(view);
        }
        this.login.start();
        mostraSchermata(this.login.getView());
    }

    @Override
    protected void visualizzaRegistrazione() {
        System.out.println("[Registrazione GUI — da implementare]");
    }

    @Override
    protected void visualizzaHomeStudente() {
        if (this.homeStudente == null) {
            this.homeStudente = new HomeStudenteGraphicControllerGUI();
            this.homeStudente.setGuiNavigator(this);
            Parent view = caricaFXML("HomeStudente.fxml", this.homeStudente);
            this.homeStudente.setView(view);
        }
        this.homeStudente.start();
        mostraSchermata(this.homeStudente.getView());
    }

    // ── ManageWallets — tutti gli entry-point riusano la stessa istanza ───────

    private ManageWalletsGraphicControllerGUI getManageWallets() {
        if (this.manageWallets == null)
            this.manageWallets = caricaManageWallets();
        return this.manageWallets;
    }

    @Override
    protected void visualizzaMercato() {
        getManageWallets().start();
        mostraSchermata(this.manageWallets.getView());
    }

    @Override
    protected void visualizzaDettaglioStock() {
        // Gestito inline dal panel dettaglio all'interno di ManageWallets.fxml
    }

    @Override
    protected void visualizzaConfermaOrdine() {
        getManageWallets().startConfermaOrdine();
        mostraSchermata(this.manageWallets.getView());
    }

    @Override
    protected void visualizzaPortafoglio() {
        getManageWallets().startPortafoglio();
        mostraSchermata(this.manageWallets.getView());
    }

    @Override
    protected void visualizzaStorico() {
        getManageWallets().startStorico();
        mostraSchermata(this.manageWallets.getView());
    }

    /**
     * Visualizza il portafoglio di studenteTarget in sola lettura.
     * Richiede impostaStudenteTarget() prima della chiamata.
     */
    @Override
    protected void visualizzaWalletStudente() {
        var target = getStudenteTarget();
        if (target == null) {
            System.err.println("[NavigatorGUI] visualizzaWalletStudente: studenteTarget non impostato");
            return;
        }
        getManageWallets().startWalletEsterno(target);
        mostraSchermata(this.manageWallets.getView());
    }

    // ── Professore ────────────────────────────────────────────────────────────

    @Override
    protected void visualizzaHomeProfessore() {
        if (this.homeProfessore == null) {
            this.homeProfessore = new HomeProfessoreGraphicControllerGUI();
            this.homeProfessore.setGuiNavigator(this);
            Parent view = caricaFXML("HomeProfessore.fxml", this.homeProfessore);
            this.homeProfessore.setView(view);
        }
        this.homeProfessore.start();
        mostraSchermata(this.homeProfessore.getView());
    }

    @Override
    protected void visualizzaGestioneClasse() {
        if (this.gestioneClasse == null) {
            this.gestioneClasse = new GestioneClasseGraphicControllerGUI();
            this.gestioneClasse.setGuiNavigator(this);
            Parent view = caricaFXML("GestioneClasse.fxml", this.gestioneClasse);
            this.gestioneClasse.setView(view);
